begin;
    with j as (select * from jsonb_to_recordset($law7v016$[{"code_id":"GK_RF_2","article_number":"787","version_date":"1994-11-30","article_text":"По договору фрахтования (чартер) одна сторона (фрахтовщик) обязуется предоставить другой стороне (фрахтователю) за плату всю или часть вместимости одного или нескольких транспортных средств на один или несколько рейсов для перевозки грузов, пассажиров и багажа.\n\nПорядок заключения договора фрахтования, а также форма указанного договора устанавливаются транспортными уставами, кодексами и иными законами. (В редакции Федерального закона от 29.12.2017 № 442-ФЗ)","article_title":"Статья 787. Договор фрахтования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b67020e78e80b2a6f70a92241586b4fb3cbf78658cdbcb37c552021619aa4f3d"},{"code_id":"GK_RF_2","article_number":"788","version_date":"1994-11-30","article_text":"Взаимоотношения транспортных организаций при перевозке грузов, пассажиров и багажа разными видами транспорта по единому транспортному документу (прямое смешанное сообщение), а также порядок организации этих перевозок определяются соглашениями между организациями соответствующих видов транспорта, заключаемыми в соответствии с законом о прямых смешанных (комбинированных) перевозках.","article_title":"Статья 788. Прямое смешанное сообщение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"624767a82d6ed3a111a37fd1f56143950176b3eed4c5e5574ef41f17c5fe3fac"},{"code_id":"GK_RF_2","article_number":"789","version_date":"1994-11-30","article_text":"Перечень организаций, обязанных осуществлять перевозки, признаваемые перевозками транспортом общего пользования, публикуется в установленном порядке.","article_title":"Статья 789. Перевозка транспортом общего пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e42cf3424c4a04435e850653603ad4175497996720b794f222e1c57f727ecd86"},{"code_id":"GK_RF_2","article_number":"790","version_date":"1994-11-30","article_text":"1. За перевозку грузов, пассажиров и багажа взимается провозная плата, установленная соглашением сторон, если иное не предусмотрено законом или иными правовыми актами.\n\n2. Плата за перевозку грузов, пассажиров и багажа транспортом общего пользования определяется на основании тарифов, утверждаемых в порядке, установленном транспортными уставами и кодексами.\n\n3. Работы и услуги, выполняемые перевозчиком по требованию грузовладельца и не предусмотренные тарифами, оплачиваются по соглашению сторон.\n\n4. Перевозчик имеет право удерживать переданные ему для перевозки грузы и багаж в обеспечение причитающихся ему провозной платы и других платежей по перевозке (статьи 359, 360), если иное не установлено законом, иными правовыми актами, договором перевозки или не вытекает из существа обязательства.\n\n5. В случаях, когда в соответствии с законом или иными правовыми актами установлены льготы или преимущества по провозной плате за перевозку грузов, пассажиров и багажа, понесенные в связи с этим расходы возмещаются транспортной организацией за счет средств соответствующего бюджета.","article_title":"Статья 790. Провозная плата","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"861c8de0be8b8ef2ba11eceb9b244d7d9c5bc57f6259b0c59ea929ac581a267c"},{"code_id":"GK_RF_2","article_number":"791","version_date":"1994-11-30","article_text":"1. Перевозчик обязан подать отправителю груза под погрузку в срок, установленный принятой от него заявкой (заказом), договором перевозки или договором об организации перевозок, исправные транспортные средства в состоянии, пригодном для перевозки соответствующего груза.\n\nОтправитель груза вправе отказаться от поданных транспортных средств, не пригодных для перевозки соответствующего груза.\n\n2. Погрузка (выгрузка) груза осуществляется транспортной организацией или отправителем (получателем) в порядке, предусмотренном договором, с соблюдением положений, установленных транспортными уставами и кодексами и издаваемыми в соответствии с ними правилами.\n\n3. Погрузка (выгрузка) груза, осуществляемая силами и средствами отправителя (получателя) груза, должна производиться в сроки, предусмотренные договором, если такие сроки не установлены транспортными уставами и кодексами и издаваемыми в соответствии с ними правилами.","article_title":"Статья 791. Подача транспортных средств, погрузка и выгрузка груза","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51387161f82d24d3b4d1f6d2b47f0935e83d15b060eb25027de75a8be246abac"},{"code_id":"GK_RF_2","article_number":"792","version_date":"1994-11-30","article_text":"Перевозчик обязан доставить груз, пассажира или багаж в пункт назначения в сроки, определенные в порядке, предусмотренном транспортными уставами, кодексами и иными законами, а при отсутствии таких сроков в разумный срок. (В редакции Федерального закона от 29.12.2017 № 442-ФЗ)","article_title":"Статья 792. Сроки доставки груза, пассажира и багажа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6be695fd72955e5dc158de6de586d63fa40bffec9467b5824a198e0eb492ba9d"},{"code_id":"GK_RF_2","article_number":"794","version_date":"1994-11-30","article_text":"1. Перевозчик за неподачу транспортных средств для перевозки груза в соответствии с принятой заявкой (заказом) или иным договором, а отправитель за непредъявление груза либо неиспользование поданных транспортных средств по иным причинам несут ответственность, установленную транспортными уставами и кодексами, а также соглашением сторон.\n\n2. Перевозчик и отправитель груза освобождаются от ответственности в случае неподачи транспортных средств либо неиспользования поданных транспортных средств, если это произошло вследствие:\n\nнепреодолимой силы, а также иных явлений стихийного характера (пожаров, заносов, наводнений) и военных действий;\n\nпрекращения или ограничения перевозки грузов в определенных направлениях, установленного в порядке, предусмотренном соответствующим транспортным уставом или кодексом;\n\nв иных случаях, предусмотренных транспортными уставами и кодексами.","article_title":"Статья 794. Ответственность перевозчика за неподачу транспортных средств и отправителя за неиспользование поданных транспортных средств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76454535d21257cdfdae37e0dc96a08b74631893bfae47f6d14386fdbcf4af74"},{"code_id":"GK_RF_2","article_number":"795","version_date":"1994-11-30","article_text":"1. За задержку отправления транспортного средства, перевозящего пассажира, или опоздание прибытия такого транспортного средства в пункт назначения (за исключением перевозок в городском и пригородном сообщениях) перевозчик уплачивает пассажиру штраф в размере, установленном соответствующим транспортным уставом или кодексом, если не докажет, что задержка или опоздание имели место вследствие непреодолимой силы, устранения неисправности транспортных средств, угрожающей жизни и здоровью пассажиров, или иных обстоятельств, не зависящих от перевозчика.\n\n2. В случае отказа пассажира от перевозки из-за задержки отправления транспортного средства перевозчик обязан возвратить пассажиру провозную плату.","article_title":"Статья 795. Ответственность перевозчика за задержку отправления пассажира","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1965a430c73d6af45b1cf87aee4959fcf52994c8682938af102c7f3d0ff9251b"},{"code_id":"GK_RF_2","article_number":"796","version_date":"1994-11-30","article_text":"1. Перевозчик несет ответственность за несохранность груза или багажа, происшедшую после принятия его к перевозке и до выдачи грузополучателю, управомоченному им лицу или лицу, управомоченному на получение багажа, если не докажет, что утрата, недостача или повреждение (порча) груза или багажа произошли вследствие обстоятельств, которые перевозчик не мог предотвратить и устранение которых от него не зависело.\n\n2. Ущерб, причиненный при перевозке груза или багажа, возмещается перевозчиком:\n\nв случае утраты или недостачи груза или багажа - в размере стоимости утраченного или недостающего груза или багажа;\n\nв случае повреждения (порчи) груза или багажа - в размере суммы, на которую понизилась его стоимость, а при невозможности восстановления поврежденного груза или багажа - в размере его стоимости;\n\nв случае утраты груза или багажа, сданного к перевозке с объявлением его ценности, - в размере объявленной стоимости груза или багажа.\n\nСтоимость груза или багажа определяется исходя из его цены, указанной в счете продавца или предусмотренной договором, а при отсутствии счета или указания цены в договоре исходя из цены, которая при сравнимых обстоятельствах обычно взимается за аналогичные товары.\n\n3. Перевозчик наряду с возмещением установленного ущерба, вызванного утратой, недостачей или повреждением (порчей) груза или багажа, возвращает отправителю (получателю) провозную плату, взысканную за перевозку утраченного, недостающего, испорченного или поврежденного груза или багажа, если эта плата не входит в стоимость груза.\n\n4. Документы о причинах несохранности груза или багажа (коммерческий акт, акт общей формы и т.п.), составленные перевозчиком в одностороннем порядке, подлежат в случае спора оценке судом наряду с другими документами, удостоверяющими обстоятельства, которые могут служить основанием для ответственности перевозчика, отправителя либо получателя груза или багажа.","article_title":"Статья 796. Ответственность перевозчика за утрату, недостачу и повреждение (порчу) груза или багажа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1902861f692647fcbabc87768aaaa68546f1ab394d8e235015bceda908369886"},{"code_id":"GK_RF_2","article_number":"797","version_date":"1994-11-30","article_text":"1. До предъявления к перевозчику иска, вытекающего из перевозки груза, обязательно предъявление ему претензии в порядке, предусмотренном соответствующим транспортным уставом или кодексом.\n\n2. Иск к перевозчику может быть предъявлен грузоотправителем или грузополучателем в случае полного или частичного отказа перевозчика удовлетворить претензию либо неполучения от перевозчика ответа в тридцатидневный срок.\n\n3. Срок исковой давности по требованиям, вытекающим из перевозки груза, устанавливается в один год с момента, определяемого в соответствии с транспортными уставами и кодексами.","article_title":"Статья 797. Претензии и иски по перевозкам грузов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e9e70e24378e4ee421a4fb4e50edf64e107ef55d17542a81cec73d29d7f89ce9"},{"code_id":"GK_RF_2","article_number":"798","version_date":"1994-11-30","article_text":"Перевозчик и грузовладелец при необходимости осуществления систематических перевозок грузов могут заключать долгосрочные договоры об организации перевозок.\n\nПо договору об организации перевозки грузов перевозчик обязуется в установленные сроки принимать, а грузовладелец - предъявлять к перевозке грузы в обусловленном объеме. В договоре об организации перевозки грузов определяются объемы, сроки и другие условия предоставления транспортных средств и предъявления грузов для перевозки, порядок расчетов, а также иные условия организации перевозки.","article_title":"Статья 798. Договоры об организации перевозок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7a9e7404152c7f283bf10d3fb076dca3a93fe20640f443f7feb7c64fda4eb66e"},{"code_id":"GK_RF_2","article_number":"799","version_date":"1994-11-30","article_text":"Между организациями различных видов транспорта могут заключаться договоры об организации работы по обеспечению перевозок грузов (узловые соглашения, договоры на централизованный завоз (вывоз) грузов и другие).\n\nПорядок заключения таких договоров определяется транспортными уставами и кодексами, другими законами и иными правовыми актами.","article_title":"Статья 799. Договоры между транспортными организациями","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77ae940b4cb4ecf75dd1d9e4f57e09d9b190e09648bf9b92200d7eeba3316c06"},{"code_id":"GK_RF_2","article_number":"800","version_date":"1994-11-30","article_text":"Ответственность перевозчика за вред, причиненный жизни или здоровью пассажира, определяется по правилам главы 59 настоящего Кодекса, если законом или договором перевозки не предусмотрена повышенная ответственность перевозчика.","article_title":"Статья 800. Ответственность перевозчика за причинение вреда жизни или здоровью пассажира","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0af872a1dc58f1cee7ae4ec3f321eb4232c58326b363660703d70b099b36a0c7"},{"code_id":"GK_RF_2","article_number":"801","version_date":"1994-11-30","article_text":"1. По договору транспортной экспедиции одна сторона (экспедитор) обязуется за вознаграждение и за счет другой стороны (клиента - грузоотправителя или грузополучателя) выполнить или организовать выполнение определенных договором экспедиции услуг, связанных с перевозкой груза.\n\nДоговором транспортной экспедиции могут быть предусмотрены обязанности экспедитора организовать перевозку груза транспортом и по маршруту, избранными экспедитором или клиентом, обязанность экспедитора заключить от имени клиента или от своего имени договор (договоры) перевозки груза, обеспечить отправку и получение груза, а также другие обязанности, связанные с перевозкой.\n\nВ качестве дополнительных услуг договором транспортной экспедиции может быть предусмотрено осуществление таких необходимых для доставки груза операций, как получение требующихся для экспорта или импорта документов, выполнение таможенных и иных формальностей, проверка количества и состояния груза, его погрузка и выгрузка, уплата пошлин, сборов и других расходов, возлагаемых на клиента, хранение груза, его получение в пункте назначения, а также выполнение иных операций и услуг, предусмотренных договором.\n\n2. Правила настоящей главы распространяются и на случаи, когда в соответствии с договором обязанности экспедитора исполняются перевозчиком.\n\n3. Условия выполнения договора транспортной экспедиции определяются соглашением сторон, если иное не установлено законом о транспортно-экспедиционной деятельности, другими законами или иными правовыми актами.","article_title":"Статья 801. Договор транспортной экспедиции","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71a51223581b061c6869675bfa9788777e9e6019a2edbd0e5710f31b904648f3"},{"code_id":"GK_RF_2","article_number":"802","version_date":"1994-11-30","article_text":"1. Договор транспортной экспедиции заключается в письменной форме.\n\n2. Клиент должен выдать экспедитору доверенность, если она необходима для выполнения его обязанностей.","article_title":"Статья 802. Форма договора транспортной экспедиции","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be65997f62c48a589c648f59b02a19527b027879f8b45ea045953d31c49fbf0f"},{"code_id":"GK_RF_2","article_number":"803","version_date":"1994-11-30","article_text":"За неисполнение или ненадлежащее исполнение обязанностей по договору экспедиции экспедитор несет ответственность по основаниям и в размере, которые определяются в соответствии с правилами главы 25 настоящего Кодекса.\n\nЕсли экспедитор докажет, что нарушение обязательства вызвано ненадлежащим исполнением договоров перевозки, ответственность экспедитора перед клиентом определяется по тем же правилам, по которым перед экспедитором отвечает соответствующий перевозчик.","article_title":"Статья 803. Ответственность экспедитора по договору транспортной экспедиции","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ccbb36b59371a3806ccae397e750487d4bf3ac60fa514ea3d2b3cb158dc8e1bc"},{"code_id":"GK_RF_2","article_number":"804","version_date":"1994-11-30","article_text":"1. Клиент обязан предоставить экспедитору документы и другую информацию о свойствах груза, об условиях его перевозки, а также иную информацию, необходимую для исполнения экспедитором обязанности, предусмотренной договором транспортной экспедиции.\n\n2. Экспедитор обязан сообщить клиенту об обнаруженных недостатках полученной информации, а в случае неполноты информации запросить у клиента необходимые дополнительные данные.\n\n3. В случае непредоставления клиентом необходимой информации экспедитор вправе не приступать к исполнению соответствующих обязанностей до предоставления такой информации.\n\n4. Клиент несет ответственность за убытки, причиненные экспедитору в связи с нарушением обязанности по предоставлению информации, указанной в пункте 1 настоящей статьи.","article_title":"Статья 804. Документы и другая информация, предоставляемые экспедитору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c74d584a5546aba10257f661d874ca5f2645e3c31c6ed79c237548dc0010847c"},{"code_id":"GK_RF_2","article_number":"805","version_date":"1994-11-30","article_text":"Если из договора транспортной экспедиции не следует, что экспедитор должен исполнить свои обязанности лично, экспедитор вправе привлечь к исполнению своих обязанностей других лиц.\n\nВозложение исполнения обязательства на третье лицо не освобождает экспедитора от ответственности перед клиентом за исполнение договора.","article_title":"Статья 805. Исполнение обязанностей экспедитора третьим лицом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a22b80de83078342510c5afba2b5681a80f0635078697d8a26c82438b521610c"},{"code_id":"GK_RF_2","article_number":"806","version_date":"1994-11-30","article_text":"Любая из сторон вправе отказаться от исполнения договора транспортной экспедиции, предупредив об этом другую сторону в разумный срок.\n\nПри одностороннем отказе от исполнения договора сторона, заявившая об отказе, возмещает другой стороне убытки, вызванные расторжением договора.","article_title":"Статья 806. Односторонний отказ от исполнения договора транспортной экспедиции","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5dccc769f5550ad61bc17e40c1c4c81514c8bc22703f8e9d8bbc475264497d7e"},{"code_id":"GK_RF_2","article_number":"807","version_date":"1994-11-30","article_text":"1. По договору займа одна сторона (займодавец) перед\n\nает или обязуется передать в собственность другой стороне (заемщику) деньги, вещи, определенные родовыми признаками, или ценные бумаги, а заемщик обязуется возвратить займодавцу такую же сумму денег (сумму займа) или равное количество полученных им вещей того же рода и качества либо таких же ценных бумаг.\n\nЕсли займодавцем в договоре займа является гражданин, договор считается заключенным с момента передачи суммы займа или другого предмета договора займа заемщику или указанному им лицу.\n\n2. Иностранная валюта и валютные ценности могут быть предметом договора займа на территории Российской Федерации с соблюдением правил статей 140, 141 и 317 настоящего Кодекса.\n\n3. Если займодавец в силу договора займа обязался предоставить заем, он вправе отказаться от исполнения договора полностью или частично при наличии обстоятельств, очевидно свидетельствующих о том, что предоставленный заем не будет возвращен в срок.\n\nЗаемщик по договору займа, в силу которого займодавец обязался предоставить заем, вправе отказаться от получения займа полностью или частично, уведомив об этом займодавца до установленного договором срока передачи предмета займа, а если такой срок не установлен, в любое время до момента получения займа, если иное не предусмотрено законом, иными правовыми актами или договором займа, заемщиком по которому является лицо, осуществляющее предпринимательскую деятельность.\n\n4. Договор займа может быть заключен путем размещения облигаций. Если договор займа заключен путем размещения облигаций, в облигации или в закрепляющем права по облигации документе указывается право ее держателя на получение в предусмотренный ею срок от лица, выпустившего облигацию, номинальной стоимости облигации или иного имущественного эквивалента.\n\n5. Сумма займа или другой предмет договора займа, переданные указанному заемщиком третьему лицу, считаются переданными заемщику.\n\n6. Заемщик - юридическое лицо вправе привлекать денежные средства граждан в виде займа под проценты путем публичной оферты либо путем предложения делать оферту, направленного неопределенному кругу лиц, если законом такому юридическому лицу предоставлено право на привлечение денежных средств граждан. Правило настоящего пункта не применяется к выпуску облигаций.\n\n7. Особенности предоставления займа под проценты заемщику-гражданину в целях, не связанных с предпринимательской деятельностью, устанавливаются законами.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 807. Договор займа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"861fc1fc36b7e2c393bf7b5462e6cb8e513e781df3f76094f8ca1bf36e762cd0"},{"code_id":"GK_RF_2","article_number":"809","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором займа, займодавец имеет право на получение с заемщика процентов за пользование займом в размерах и в порядке, определенных договором. При отсутствии в договоре условия о размере процентов за пользование займом их размер определяется ключевой ставкой Банка России, действовавшей в соответствующие периоды.\n\n2. Размер процентов за пользование займом может быть установлен в договоре с применением ставки в процентах годовых в виде фиксированной величины, с применением ставки в процентах годовых, величина которой может изменяться в зависимости от предусмотренных договором условий, в том числе в зависимости от изменения переменной величины, либо иным путем, позволяющим определить надлежащий размер процентов на момент их уплаты.\n\n3. При отсутствии иного соглашения проценты за пользование займом выплачиваются ежемесячно до дня возврата займа включительно.\n\n4. Договор займа предполагается беспроцентным, если в нем прямо не предусмотрено иное, в случаях, когда:\n\nдоговор заключен между гражданами, в том числе индивидуальными предпринимателями, на сумму, не превышающую ста тысяч рублей;\n\nпо договору заемщику передаются не деньги, а другие вещи, определенные родовыми признаками.\n\n5. Размер процентов за пользование займом по договору займа, заключенному между гражданами или между юридическим лицом, не осуществляющим профессиональной деятельности по предоставлению потребительских займов, и заемщиком-гражданином, в два и более раза превышающий обычно взимаемые в подобных случаях проценты и поэтому являющийся чрезмерно обременительным для должника (ростовщические проценты), может быть уменьшен судом до размера процентов, обычно взимаемых при сравнимых обстоятельствах.\n\n6. В случае возврата досрочно займа, предоставленного под проценты в соответствии с пунктом 2 статьи 810 настоящего Кодекса, займодавец имеет право на получение с заемщика процентов по договору займа, начисленных включительно до дня возврата суммы займа полностью или ее части.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 809. Проценты по договору займа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a93672976fab6e52cea711bf115c881ec9797f7d46cf5d15f10e9d2b3705cdfd"},{"code_id":"GK_RF_2","article_number":"810","version_date":"1994-11-30","article_text":"1. Заемщик обязан возвратить займодавцу полученную сумму займа в срок и в порядке, которые предусмотрены договором займа.\n\nВ случаях, когда срок возврата договором не установлен или определен моментом востребования, сумма займа должна быть возвращена заемщиком в течение тридцати дней со дня предъявления займодавцем требования об этом, если иное не предусмотрено договором.\n\nСумма займа, предоставленного под проценты заемщику-гражданину для личного, семейного, домашнего или иного использования, не связанного с предпринимательской деятельностью, может быть возвращена заемщиком-гражданином досрочно полностью или по частям при условии уведомления об этом займодавца не менее чем за тридцать дней до дня такого возврата. Договором займа может быть установлен более короткий срок уведомления займодавца о намерении заемщика возвратить денежные средства досрочно. (В редакции Федерального закона от 19.10.2011 № 284-ФЗ)\n\nСумма займа, предоставленного под проценты в иных случаях, может быть возвращена досрочно с согласия займодавца, в том числе согласия, выраженного в договоре займа. (Дополнение абзацем - Федеральный закон от 19.10.2011 № 284-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 810. Обязанность заемщика возвратить сумму займа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"48df85ca150ed9868a5454f8873286f91bd30dd94101f97461b364a624b122ea"},{"code_id":"GK_RF_2","article_number":"811","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором займа, в случаях, когда заемщик не возвращает в срок сумму займа, на эту сумму подлежат уплате проценты в размере, предусмотренном пунктом 1 статьи 395 настоящего Кодекса, со дня, когда она должна была быть возвращена, до дня ее возврата займодавцу независимо от уплаты процентов, предусмотренных пунктом 1 статьи 809 настоящего Кодекса.","article_title":"Статья 811. Последствия нарушения заемщиком договора займа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f9fa32e46e11668552c37296765d020baa9fbd045af6f48a241737b2f48953f6"},{"code_id":"GK_RF_2","article_number":"812","version_date":"1994-11-30","article_text":"1. Заемщик вправе доказывать, что предмет договора займа в действительности не поступил в его распоряжение или поступил не полностью (оспаривание займа по безденежности).\n\n2. Если договор займа должен быть совершен в письменной форме (статья 808), оспаривание займа по безденежности путем свидетельских показаний не допускается, за исключением случаев, когда договор был заключен под влиянием обмана, насилия, угрозы или стечения тяжелых обстоятельств, а также представителем заемщика в ущерб его интересам.\n\n3. В случае оспаривания займа по безденежности размер обязательств заемщика определяется исходя из переданных ему или указанному им третьему лицу сумм денежных средств или иного имущества.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 812. Оспаривание займа по безденежности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0be59a52e5b061182b8ab200111ab2fc70b99be2900ac622f1548cfa3dff1681"},{"code_id":"GK_RF_2","article_number":"813","version_date":"1994-11-30","article_text":"При невыполнении заемщиком предусмотренных договором займа обязанностей по обеспечению возврата займа, а также при утрате обеспечения или ухудшении его условий по обстоятельствам, за которые займодавец не отвечает, займодавец вправе потребовать от заемщика досрочного возврата займа и уплаты причитающихся на момент возврата процентов за пользование займом, если иное не предусмотрено договором займа. Причитающиеся за пользование займом проценты уплачиваются заемщиком по правилам пункта 2 статьи 811 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 813. Последствия утраты обеспечения обязательств заемщика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6fbb3832e6368e2a1a3d7e05e903ac3090bc9c640c205c2b811e3e61fc0db61d"},{"code_id":"GK_RF_2","article_number":"814","version_date":"1994-11-30","article_text":"Причитающиеся за пользование займом проценты уплачиваются заемщиком по правилам пункта 2 статьи 811 настоящего Кодекса.\n\n(Пункт в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 814. Целевой заем","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0044aaff6fdc748e5b0157311c5940c2946c510cddbf49382dbfe4ff58c49119"},{"code_id":"GK_RF_2","article_number":"815","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 815. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f585a950294350d7f22a15436a86dd4ded62f65af35684669f69f1df695d9ea5"},{"code_id":"GK_RF_2","article_number":"816","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 816. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f585a950294350d7f22a15436a86dd4ded62f65af35684669f69f1df695d9ea5"},{"code_id":"GK_RF_2","article_number":"817","version_date":"1994-11-30","article_text":"1. По договору государственного займа заемщиком выступает Российская Федерация, субъект Российской Федерации, а займодавцем - гражданин или юридическое лицо.\n\n2. Государственные займы являются добровольными.\n\n3. Договор государственного займа заключается путем приобретения займодавцем выпущенных государственных облигаций или иных государственных ценных бумаг, удостоверяющих право займодавца на получение от заемщика предоставленных ему взаймы денежных средств или, в зависимости от условий займа, иного имущества, установленных процентов либо иных имущественных прав в сроки, предусмотренные условиями выпуска займа в обращение.\n\nДоговор государственного займа может быть заключен также в иных формах, предусмотренных бюджетным законодательством. (Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)\n\n4. Изменение условий выпущенного в обращение займа не допускается.\n\n5. Правила о договоре государственного займа соответственно применяются к займам, выпускаемым муниципальным образованием.","article_title":"Статья 817. Договор государственного займа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5365e265b99f97e1542b510816795e922f9607b5df2cbcf3aca4079e6db8afad"},{"code_id":"GK_RF_2","article_number":"819","version_date":"1994-11-30","article_text":"В случае предоставления кредита гражданину в целях, не связанных с осуществлением предпринимательской деятельности (в том числе кредита, обязательства заемщика по которому обеспечены ипотекой), ограничения, случаи и особенности взимания иных платежей, указанных в абзаце первом настоящего пункта, определяются законом о потребительском кредите (займе). (Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 819. Кредитный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fcaf199d4eea7eb7de16b5894c02b79814f7c30936582ce666b746bfef6ac10a"},{"code_id":"GK_RF_2","article_number":"820","version_date":"1994-11-30","article_text":"Кредитный договор должен быть заключен в письменной форме.\n\nНесоблюдение письменной формы влечет недействительность кредитного договора. Такой договор считается ничтожным.","article_title":"Статья 820. Форма кредитного договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e3320c5000275bfa15e7438e09c14f54e8a81305e270536db1e5d502a07de68"},{"code_id":"GK_RF_2","article_number":"821","version_date":"1994-11-30","article_text":"1. Кредитор вправе отказаться от предоставления заемщику предусмотренного кредитным договором кредита полностью или частично при наличии обстоятельств, очевидно свидетельствующих о том, что предоставленная заемщику сумма не будет возвращена в срок.\n\n2. Заемщик вправе отказаться от получения кредита полностью или частично, уведомив об этом кредитора до установленного договором срока его предоставления, если иное не предусмотрено законом, иными правовыми актами или кредитным договором.\n\n3. В случае нарушения заемщиком предусмотренной кредитным договором обязанности целевого использования кредита (статья 814) кредитор вправе также отказаться от дальнейшего кредитования заемщика по договору.","article_title":"Статья 821. Отказ от предоставления или получения кредита","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7d68afb8d134a0e58efee85784b8c9ea36d3f42e70ad9510da24a18b75079010"},{"code_id":"GK_RF_2","article_number":"821.1","version_date":"1994-11-30","article_text":"Кредитор вправе требовать досрочного возврата кредита в случаях, предусмотренных настоящим Кодексом, другими законами, а при предоставлении кредита юридическому лицу или индивидуальному предпринимателю также в случаях, предусмотренных кредитным договором.\n\n(Дополнение статьей - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 821.1. Требование кредитора о досрочном возврате кредита","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97ba4fbbd53a7aac1ef5bb9f116da79f54e529255e4bbfbbebbbe3be7a39e0a1"},{"code_id":"GK_RF_2","article_number":"822","version_date":"1994-11-30","article_text":"Сторонами может быть заключен договор, предусматривающий обязанность одной стороны предоставить другой стороне вещи, определенные родовыми признаками (договор товарного кредита). К такому договору применяются правила параграфа 1 настоящей главы, если иное не предусмотрено таким договором и не вытекает из существа обязательства. (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\nУсловия о количестве, об ассортименте, о комплектности, о качестве, о таре и (или) об упаковке предоставляемых вещей должны исполняться в соответствии с правилами о договоре купли-продажи товаров (статьи 465 - 485), если иное не предусмотрено договором товарного кредита.","article_title":"Статья 822. Товарный кредит","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"afd14c83ad0b10e5627b5d50fcf12f4ed49248bc1ae717fbc77df123bc41a0cc"},{"code_id":"GK_RF_2","article_number":"823","version_date":"1994-11-30","article_text":"1. Договорами, исполнение которых связано с передачей в собственность другой стороне денежных сумм или других вещей, определяемых родовыми признаками, может предусматриваться предоставление кредита, в том числе в виде аванса, предварительной оплаты, отсрочки и рассрочки оплаты товаров, работ или услуг (коммерческий кредит), если иное не установлено законом.\n\n2. К коммерческому кредиту соответственно применяются правила настоящей главы, если иное не предусмотрено правилами о договоре, из которого возникло соответствующее обязательство, и не противоречит существу такого обязательства.","article_title":"Статья 823. Коммерческий кредит","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4973513ede2c0c587159ff087c3739438a241697bd93e07c7418b32453c8c14c"},{"code_id":"GK_RF_2","article_number":"824","version_date":"1994-11-30","article_text":"1. По договору финансирования под уступку денежного требования (договору факторинга) одна сторона (клиент) обязуется уступить другой стороне - финансовому агенту (фактору) денежные требования к третьему лицу (должнику) и оплатить оказанные услуги, а финансовый агент (фактор) обязуется совершить не менее двух следующих действий, связанных с денежными требованиями, являющимися предметом уступки:\n\n1) передавать клиенту денежные средства в счет денежных требований, в том числе в виде займа или предварительного платежа (аванса);\n\n2) осуществлять учет денежных требований клиента к третьим лицам (должникам);\n\n3) осуществлять права по денежным требованиям клиента, в том числе предъявлять должникам денежные требования к оплате, получать платежи от должников и производить расчеты, связанные с денежными требованиями;\n\n4) осуществлять права по договорам об обеспечении исполнения обязательств должников.\n\n2. Обязательства финансового агента (фактора) по договору факторинга могут включать ведение для клиента бухгалтерского учета, а также предоставление клиенту иных услуг, связанных с денежными требованиями, являющимися предметом уступки.\n\n3. В части, не урегулированной настоящей главой, к отношениям, связанным с уступкой права требования по договору факторинга, применяются правила главы 24 настоящего Кодекса.\n\n4. Участники гражданского оборота могут заключать также иные договоры, в соответствии с которыми осуществляется уступка денежных требований и которые предусматривают обязанность одной из сторон совершить одно или несколько действий, указанных в подпунктах 1 - 4 пункта 1 настоящей статьи.\n\n5. Если в силу договора факторинга финансовый агент (фактор) несет обязанности по оплате цены приобретенных им денежных требований, по предоставлению клиенту займа (кредита) или по оказанию клиенту услуг, к отношениям сторон по договору факторинга применяются правила соответственно о купле-продаже, займе (кредите), возмездном оказании услуг постольку, поскольку это не противоречит положениям настоящей главы и существу отношений по договору факторинга.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 824. Договор финансирования под уступку денежного требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"23e5ebccbd9093c95860c860a88b38a54b3bfc5331ceb1c5ddb88662c93b79a3"},{"code_id":"GK_RF_2","article_number":"825","version_date":"1994-11-30","article_text":"В качестве финансового агента договоры факторинга могут заключать коммерческие организации. (В редакции федеральных законов от 26.07.2017 № 212-ФЗ)\n\n(Статья в редакции федеральных законов от 09.04.2009 № 56-ФЗ)","article_title":"Статья 825. Финансовый агент","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8228ebce9545336edba94f01c0c7b6b062098373b17eae178ef721dd997911a"},{"code_id":"GK_RF_2","article_number":"826","version_date":"1994-11-30","article_text":"1. Предметом уступки по договору факторинга могут быть денежное требование или денежные требования:\n\n1) по существующему обязательству, в том числе по обязательству, возникшему из заключенного договора, срок платежа по которому наступил либо не наступил (существующее требование);\n\n2) по обязательству, которое возникнет в будущем, в том числе из договора, который будет заключен в будущем (будущее требование) (статья 3881).\n\n2. Денежное требование переходит к финансовому агенту (фактору) в момент заключения договора факторинга, если иное не установлено таким до\n\nговором. При этом будущее требование переходит к финансовому агенту (фактору) с момента его возникновения, если договором не предусмотрено, что будущее требование переходит позднее.\n\n3. Если договор факторинга заключен ранее момента перехода денежного требования к финансовому агенту (фактору), дополнительное оформление перехода денежного требования не требуется.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 826. Денежное требование, являющееся предметом уступки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a56270fa00757ec38a0f5ab9034a999469c7febc5c0bba514643dc8a38f1c4a3"},{"code_id":"GK_RF_2","article_number":"829","version_date":"1994-11-30","article_text":"1. Если уступка денежного требования финансовому агенту (фактору) осуществлена в целях приобретения им указанного требования, последующая уступка денежного требования финансовым агентом (фактором) допускается, если договором факторинга не предусмотрено иное.\n\n2. Если уступка денежного требования финансовому агенту (фактору) осуществлена в целях обеспечения исполнения обязательства клиента перед финансовым агентом (фактором) или в целях оказания финансовым агентом (фактором) клиенту услуг, связанных с денежными требованиями, являющимися предметом уступки, последующая уступка денежного требования финансовым агентом (фактором) не допускается, если договором факторинга не предусмотрено иное.\n\n3. К последующей уступке денежного требования финансовым агентом (фактором) применяются соответственно положения настоящей главы.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 829. Последующая уступка денежного требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b7be3e4c6b8bca236641d7770e14d032edc34f0590ce5ad55ff10c061ce3b4a4"},{"code_id":"GK_RF_2","article_number":"831","version_date":"1994-11-30","article_text":"1. Если уступка денежного требования по договору факторинга осуществлена в целях приобретения этого требования финансовым агентом (фактором), последний приобретает право на все суммы, которые он получит от должника во исполнение указанного требования, а клиент не несет ответственности перед финансовым агентом (фактором) за то, что полученные им суммы оказались меньше цены, за которую агент приобрел указанное требование, если иное не предусмотрено договором.\n\n2. Если уступка денежного требования финансовому агенту (фактору) осуществлена в целях обеспечения исполнения обязательства клиента перед финансовым агентом (фактором) и договором факторинга не предусмотрено иное, финансовый агент (фактор) обязан представить отчет клиенту и после получения исполнения от должника передать клиенту сумму, превышающую сумму долга клиента, обеспеченную уступкой требования. В силу уступки денежного требования в целях обеспечения исполнения обязательства клиента при получении финансовым агентом (фактором) денежных средств от должника по уступленному финансовому агенту (фактору) клиентом денежному требованию обязательство клиента перед финансовым агентом (фактором) считается надлежащим образом исполненным в том объеме, в котором должник исполнил свое обязательство перед финансовым агентом (фактором). Если денежные средства, полученные финансовым агентом (фактором) от должника, оказались меньше суммы долга клиента финансовому агенту (фактору), обеспеченной уступкой требования, клиент остается ответственным перед финансовым агентом (фактором) за остаток своего долга.\n\n3. Если уступка денежного требования осуществлена в целях оказания финансовым агентом (фактором) клиенту услуг, связанных с денежными требованиями, являющимися предметом уступки, финансовый агент (фактор) обязан представить отчет клиенту и передать ему все суммы, полученные во исполнение уступленных денежных требований, а клиент обязан оплатить оказанные услуги.\n\n4. Финансовый агент (фактор) вправе при передаче клиенту денежных средств предъявить к зачету свои денежные требования по договору.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 831. Права финансового агента (фактора) на суммы, полученные от должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e271b0ef85dc33e4dc58d3f3a7b73c61e04120a2894956617d33dc72f6bd301"},{"code_id":"GK_RF_2","article_number":"832","version_date":"1994-11-30","article_text":"1. В случае обращения финансового агента к должнику с требованием произвести платеж должник вправе в соответствии со статьями 410 - 412 настоящего Кодекса предъявить к зачету свои денежные требования, основанные на договоре с клиентом, которые уже имелись у должника ко времени, когда им было получено уведомление об уступке требования финансовому агенту.\n\n2. Требования, которые должник мог бы предъявить клиенту в связи с нарушением последним соглашения о запрете об ограничении уступки требования, не имеют силы в отношении финансового агента.","article_title":"Статья 832. Встречные требования должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c3a1b0ff8560d4b72e28d7e7fad12da9828a070d200e9025580a9cdfcc5acbd"},{"code_id":"GK_RF_2","article_number":"833","version_date":"1994-11-30","article_text":"В случае неисполнения клиентом своих обязательств по договору, заключенному с должником, последний не вправе требовать от финансового агента (фактора) возврат уплаченных ему сумм. Соответствующее требование может быть предъявлено должником клиенту.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 833. Возврат должнику сумм, полученных финансовым агентом (фактором)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"986c6d385c395fcaa12813231c0ceee382eb123a9b4200bcde30d9be9e71ca1f"},{"code_id":"GK_RF_2","article_number":"834","version_date":"1994-11-30","article_text":"Если иное не предусмотрено законом, юридические лица не вправе перечислять находящиеся во вкладах (депозитах) денежные средства другим лицам. (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 834. Договор банковского вклада","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91e840d4e7c9182424242e2405295f093e03d4abd558b706619d67ddf73abb1a"},{"code_id":"GK_RF_2","article_number":"835","version_date":"1994-11-30","article_text":"1. Право на привлечение денежных средств во вклады имеют банки, которым такое право предоставлено в соответствии с разрешением (лицензией), выданным в порядке, установленном в соответствии с законом.\n\n2. В случае принятия вклада от гражданина лицом, не имеющим на это права, или с нарушением порядка, установленного законом или принятыми в соответствии с ним банковскими правилами, вкладчик может потребовать немедленного возврата суммы вклада, а также уплаты на нее процентов, предусмотренных статьей 395 настоящего Кодекса, и возмещения сверх суммы процентов всех причиненных вкладчику убытков.\n\nЕсли таким лицом приняты на условиях договора банковского вклада денежные средства юридического лица, такой договор является недействительным (статья 168).\n\n3. Если иное не установлено законом, последствия, предусмотренные пунктом 2 настоящей статьи, применяются также в случаях:\n\nпривлечения денежных средств граждан и юридических лиц путем продажи им акций и других ценных бумаг, выпуск которых признан незаконным;\n\nпривлечения денежных средств граждан во вклады под векселя или иные ценные бумаги, исключающие получение их держателями вклада по первому требованию и осуществление вкладчиком других прав, предусмотренных правилами настоящей главы.","article_title":"Статья 835. Право на привлечение денежных средств во вклады","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06c307313c88b7f8847ae48798b50cd93e18df9799c141abf578002bffc3a61a"},{"code_id":"GK_RF_2","article_number":"836","version_date":"1994-11-30","article_text":"1. Договор банковского вклада должен быть заключен в письменной форме.\n\nПисьменная форма договора банковского вклада считается соблюденной, если внесение вклада удостоверено сберегательной книжкой, сберегательным или депозитным сертификатом либо иным выданным банком вкладчику документом, отвечающим требованиям, предусмотренным для таких документов законом, установленными в соответствии с ним банковскими правилами и применяемыми в банковской практике обычаями. (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n2. Несоблюдение письменной формы договора банковского вклада влечет недействительность этого договора. Такой договор является ничтожным.","article_title":"Статья 836. Форма договора банковского вклада","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"15cc9bc7a255a6587ecd55b9512308cbb0cf87da7b70521f5d484cd5e11861fb"},{"code_id":"GK_RF_2","article_number":"837","version_date":"1994-11-30","article_text":"1. Договор банковского вклада заключается на условиях выдачи вклада по требованию (вклад до востребования) либо на условиях возврата вклада по истечении определенного договором срока (срочный вклад). Договором может быть предусмотрено внесение вкладов на иных не противоречащих закону условиях их возврата.\n\n2. По договору вклада любого вида, заключенному с гражданином, банк в любом случае обязан выдать по первому требованию вкладчика сумму вклада или ее часть и соответствующие проценты (за исключением вкладов, внесение которых удостоверено сберегательным сертификатом, условия которого не предусматривают право вкладчика на получение вклада по требованию).\n\n3. Сроки и порядок выдачи суммы вклада или ее части и соответствующих процентов юридическому лицу по договору вклада любого вида определяются договором банковского вклада.\n\n4. Условие договора об отказе гражданина от права на получение срочного вклада или вклада до востребования по его требованию ничтожно, за исключением случая, когда внесение вклада удостоверено сберегательным сертификатом, условия которого не предусматривают право вкладчика на получение вклада по требованию.\n\n5. В случаях, когда срочный вклад возвращается вкладчику по его требованию до истечения срока либо до наступления иных обстоятельств, указанных в договоре банковского вклада, проценты по вкладу выплачиваются в размере, соответствующем размеру процентов, выплачиваемых банком по вкладам до востребования, если договором банковского вклада не предусмотрен иной размер процентов.\n\n6. В случаях, когда вкладчик не требует возврата суммы срочного вклада по истечении срока либо по наступлении предусмотренных договором обстоятельств, договор считается продленным на условиях вклада до востребования, если иное не предусмотрено договором.\n\n7. В случае, когда внесение вклада удостоверено сберегательным или депозитным сертификатом, все права по договору банковского вклада принадлежат владельцу соответствующего сертификата.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 837. Виды вкладов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"74cc11e896c3f1d78928fa92d8afa8de6e8540aa5f18c6a7679b5137aa00f5b7"},{"code_id":"GK_RF_2","article_number":"838","version_date":"1994-11-30","article_text":"1. Банк выплачивает вкладчику проценты на сумму вклада в размере, определяемом договором банковского вклада.\n\nПри отсутствии в договоре условия о размере выплачиваемых процентов банк обязан выплачивать проценты в размере, определяемом в соответствии с пунктом 1 статьи 809 настоящего Кодекса.\n\n2. Если иное не предусмотрено договором банковского вклада, банк вправе изменять размер процентов, выплачиваемых на вклады до востребования.\n\nВ случае уменьшения банком размера процентов новый размер процентов применяется к вкладам, внесенным до сообщения вкладчикам об уменьшении процентов, по истечении месяца с момента соответствующего сообщения, если иное не предусмотрено договором.","article_title":"Статья 838. Проценты на вклад","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2467a080738478513462908548605784f76be888e2226fd9616099e2ac27bccc"},{"code_id":"GK_RF_2","article_number":"839","version_date":"1994-11-30","article_text":"При возврате вклада выплачиваются все начисленные к этому моменту проценты.","article_title":"Статья 839. Порядок начисления процентов на вклад и их выплаты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2f9dd411f672a802379eb0b8e075a0c39adce0ffa2f946fcb5212454f91f10a"},{"code_id":"GK_RF_2","article_number":"841","version_date":"1994-11-30","article_text":"Если договором банковского вклада не предусмотрено иное, на счет по вкладу зачисляются денежные средства, поступившие в банк на имя вкладчика от третьих лиц с указанием необходимых данных о его счете по вкладу. При этом предполагается, что вкладчик выразил согласие на получение денежных средств от таких лиц, предоставив им необходимые данные о счете по вкладу.","article_title":"Статья 841. Внесение третьими лицами денежных средств на счет вкладчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dfce5b47ff0af50fff27b5ac0a46758155f7bd479f0ba34781a6b5951d5f85cf"},{"code_id":"GK_RF_2","article_number":"842","version_date":"1994-11-30","article_text":"1. Вклад может быть внесен в банк на имя определенного третьего лица. Если иное не предусмотрено договором банковского вклада, такое лицо приобретает права вкладчика с момента предъявления им к банку первого требования, основанного на этих правах, либо выражения им банку иным способом намерения воспользоваться такими правами.\n\nУказание имени гражданина (статья 19) или наименования юридического лица (статья 54), в пользу которого вносится вклад, является существенным условием соответствующего договора банковского вклада.\n\nДоговор банковского вклада в пользу гражданина, умершего к моменту заключения договора, либо не существующего к этому моменту юридического лица ничтожен.\n\n2. До выражения третьим лицом намерения воспользоваться правами вкладчика лицо, заключившее договор банковского вклада, может воспользоваться правами вкладчика в отношении внесенных им на счет по вкладу денежных средств.\n\n3. Правила о договоре в пользу третьего лица (статья 430) применяются к договору банковского вклада в пользу третьего лица, если это не противоречит правилам настоящей статьи и существу банковского вклада.","article_title":"Статья 842. Вклады в пользу третьих лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"398ab7c768a4cf82f5f72a67754a3e6ee27f1cafd855a80b87b2c3cc00e87263"},{"code_id":"GK_RF_2","article_number":"843","version_date":"1994-11-30","article_text":"В сберегательной книжке должны быть указаны и удостоверены банком наименование и место нахождения банка (статья 54), а если вклад внесен в филиал, также его соответствующего филиала, номер счета по вкладу, а также все суммы денежных средств, зачисленных на счет, все суммы денежных средств, списанных со счета, и остаток денежных средств на счете на момент предъявления сберегательной книжки в банк.\n\nЕсли не доказано иное состояние вклада, данные о вкладе, указанные в сберегательной книжке, являются основанием для расчетов по вкладу между банком и вкладчиком.\n\nЕсли именная сберегательная книжка утрачена или приведена в негодное для предъявления состояние, банк по заявлению вкладчика выдает ему новую сберегательную книжку.\n\nАбзац. (Утратил силу - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 843. Сберегательная книжка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bf4d9990885aa4ed314ef39e13fea7fa7e13928a7a9403e06974905589e58e56"},{"code_id":"GK_RF_2","article_number":"844","version_date":"1994-11-30","article_text":"1. Сберегательный и депозитный сертификаты являются именными документарными ценными бумагами, удостоверяющими факт внесения вкладчиком в банк суммы вклада на условиях, указанных в соответствующем сертификате, и право владельца такого сертификата на получение по истечении установленного сертификатом срока суммы вклада и обусловленных сертификатом процентов в банке, выдавшем сертификат.\n\nВладельцем сберегательного сертификата может быть только физическое лицо, в том числе индивидуальный предприниматель.\n\nСумма вклада, внесение которой удостоверено сберегательным сертификатом, подлежит страхованию в соответствии с законом о страховании вкладов физических лиц.\n\nВладельцем депозитного сертификата может быть только юридическое лицо.\n\n2. Проценты по сберегательному или депозитному сертификату устанавливаются и выплачиваются на утвержденных банком условиях и в сроки, определенные сберегательным или депозитным сертификатом.\n\n3. Ба\n\nнк вправе выдавать сберегательные и депозитные сертификаты, условия которых не предусматривают право владельца соответствующего сертификата на получение вклада по требованию, при этом такой сертификат должен содержать указание на отсутствие права вкладчика на досрочное получение вклада по требованию.\n\n4. Если сберегательные и депозитные сертификаты предусматривают право владельца соответствующего сертификата на получение вклада по требованию, банком при досрочном предъявлении требования владельца соответствующего сертификата о выдаче денежных средств выплачиваются сумма вклада и проценты в размере, выплачиваемом по вкладам до востребования, если условиями соответствующего сертификата не установлен иной размер процентов.\n\n5. Сберегательные или депозитные сертификаты могут выдаваться на условиях обездвижения (статья 1481), в том числе обездвижения путем их хранения в выдавшем банке при условии, что такой банк в соответствии с законом вправе осуществлять хранение документарных ценных бумаг и (или) учет прав на ценные бумаги. В случае обездвижения такие сертификаты не выдаются на руки их владельцам, а права владельцев таких сертификатов закрепляются в одном сертификате, реквизиты которого устанавливаются Банком России.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 844. Сберегательный и депозитный сертификаты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fcb453991c1b3a1582d6faa053f31f5a179e34014010793ce6b69513d0473006"},{"code_id":"GK_RF_2","article_number":"844.1","version_date":"1994-11-30","article_text":"1. По договору банковского вклада, предметом которого является драгоценный металл определенного наименования (вклад в драгоценных металлах), банк обязуется возвратить вкладчику имеющийся во вкладе драгоценный металл того же наименования и той же массы либо выдать денежные средства в сумме, эквивалентной стоимости этого металла, а также выплатить предусмотренные договором проценты.\n\n2. Договор банковского вклада в драгоценных металлах должен содержать обязательное указание на наименование драгоценного металла, размер процентов по вкладу и форму их получения вкладчиком, а также порядок расчета суммы денежных средств, подлежащих выдаче, если возможность такой выдачи предусмотрена договором.\n\n3. Если иное не установлено законом или не вытекает из существа обязательства, к отношениям по договору банковского вклада в драгоценных металлах применяются правила о вкладах, предусмотренные настоящим Кодексом, в том числе правила абзаца седьмого пункта 1 статьи 64 настоящего Кодекса.\n\n4. К отношениям по договору банковского вклада в драгоценных металлах правила пункта 1 статьи 840 настоящего Кодекса об обеспечении возврата вкладов граждан путем осуществляемого в соответствии с законом страхования вкладов физических лиц не применяются, о чем гражданин должен быть уведомлен в письменной форме до заключения договора банковского вклада в драгоценных металлах, а банк должен получить от гражданина подтверждение того, что такое уведомление было совершено.\n\n(Дополнение статьей - Федеральный закон от 26.07.2017 № 212-ФЗ)\n\n(Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 844.1. Особенности договора банковского вклада в драгоценных металлах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84393a2f59fe76c60197c9910fe854b7e3d686918831b39c4caa64961ab8855f"},{"code_id":"GK_RF_2","article_number":"845","version_date":"1994-11-30","article_text":"1. По договору банковского счета банк обязуется принимать и зачислять поступающие на счет, открытый клиенту (владельцу счета), денежные средства, выполнять распоряжения клиента о перечислении и выдаче соответствующих сумм со счета и проведении других операций по счету.\n\n2. Банк может использовать имеющиеся на счете денежные средства, гарантируя право клиента беспрепятственно распоряжаться этими средствами.\n\n3. Банк не вправе определять и контролировать направления использования денежных средств клиента и устанавливать другие не предусмотренные законом или договором банковского счета ограничения права клиента распоряжаться денежными средствами по своему усмотрению.\n\n4. Права на денежные средства, находящиеся на счете, считаются принадлежащими клиенту в пределах суммы остатка, за исключением денежных средств, в отношении которых получателю денежных средств и (или) обслуживающему его банку в соответствии с банковскими правилами и договором подтверждена возможность исполнения распоряжения клиента о списании денежных средств в течение определенного договором срока, но не более чем десять дней. По истечении указанного срока находящиеся на счете денежные средства, в отношении которых была подтверждена возможность исполнения распоряжения клиента, считаются принадлежащими клиенту.\n\n5. В случае заключения договора банковского счета с несколькими клиентами (совместный счет) такими клиентами могут быть только физические лица с учетом ограничений, установленных валютным законодательством Российской Федерации. Права на денежные средства, находящиеся на счете, считаются принадлежащими таким лицам в долях, определяемых пропорционально суммам денежных средств, внесенных каждым из клиентов или третьими лицами в пользу каждого из клиентов, если иное не предусмотрено договором банковского счета (договором установлена непропорциональность). В случае, когда договор банковского счета заключен клиентами-супругами, права на денежные средства, находящиеся на совместном счете, являются общими правами клиентов-супругов (статья 256), если иное не предусмотрено брачным договором, о заключении которого клиенты-супруги уведомили банк.\n\n6. Правила настоящей главы, относящиеся к банкам, применяются также и к другим кредитным организациям при заключении и исполнении ими договора банковского счета в соответствии с выданным разрешением (лицензией).\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 845. Договор банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e872fc8385f4b48e76254dca6d4c1bfe1464aebb68c1304211504a6ad8a9414c"},{"code_id":"GK_RF_2","article_number":"846","version_date":"1994-11-30","article_text":"1. При заключении договора банковского счета клиенту или указанному им лицу открывается счет в банке на условиях, согласованных сторонами.\n\n2. Банк обязан заключить договор банковского счета с клиентом, обратившимся с предложением открыть счет на объявленных банком для открытия счетов данного вида условиях, соответствующих требованиям, предусмотренным законом и установленными в соответствии с ним банковскими правилами.\n\nБанк не вправе отказать в открытии счета, совершение соответствующих операций по которому предусмотрено законом, уставом банка и выданным ему разрешением (лицензией), за исключением случаев, когда такой отказ вызван отсутствием у банка возможности принять на банковское обслуживание либо допускается законом или иными правовыми актами.\n\nПри необоснованном уклонении банка от заключения договора банковского счета клиент вправе предъявить ему требования, предусмотренные пунктом 4 статьи 445 настоящего Кодекса.\n\n3. Банковский счет может быть открыт на условиях использования электронного средства платежа.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 846. Заключение договора банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"016b16050d4b5a8be251b6b6b10e9d2892328fdb5de2eb8a79a0f7ce9275386c"},{"code_id":"GK_RF_2","article_number":"847","version_date":"1994-11-30","article_text":"1. Права лиц, осуществляющих от имени клиента распоряжения о перечислении и выдаче средств со счета, удостоверяются клиентом путем представления банку документов, предусмотренных законом, установленными в соответствии с ним банковскими правилами и договором банковского счета.\n\n2. Клиент может дать распоряжение банку о списании денежных средств со счета по требованию третьих лиц, в том числе связанному с исполнением клиентом своих обязательств перед этими лицами. Банк принимает эти распоряжения при условии указания в них в письменной форме необходимых данных, позволяющих при предъявлении соответствующего требования идентифицировать лицо, имеющее право на его предъявление.\n\n3. Банк исполняет распоряжение о списании денежных средств при недостаточности денежных средств на банковском счете, если этот счет включен в соответствии с договором банковского счета в группу банковских счетов, в том числе принадлежащих разным лицам, и на всех банковских счетах, включенных в указанную группу, достаточно денежных средств для исполнения распоряжения клиента. При этом такое списание не является кредитованием счета.\n\n4. Договором может быть предусмотрено удостоверение прав распоряжения денежными суммами, находящимися на счете, электронными средствами платежа и иными способами с использованием в них аналогов собственноручной подписи (пункт 2 статьи 160), кодов, паролей и других средств, подтверждающих, что распоряжение дано уполномоченным на это лицом.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 847. Порядок распоряжения денежными средствами, находящимися на счете","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"20797fb43920e158586a278099d627671bad5ad135312ad1de389bfaaf822882"},{"code_id":"GK_RF_2","article_number":"848","version_date":"1994-11-30","article_text":"1. Банк обязан совершать для клиента операции, предусмотренные для счетов данного вида законом, установленными в соответствии с ним банковскими правилами и применяемыми в банковской практике обычаями, если договором банковского счета не предусмотрено иное.\n\n2. Законом могут быть предусмотрены случаи, когда банк обязан отказать в зачислении на счет клиента денежных средств или их списании со счета клиента.\n\n3. Если иное не установлено законом, договором банковского счета могут быть предусмотрены случаи, когда банк обязан отказать в зачислении на счет клиента денежных средств или в их списании со счета клиента.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 848. Операции по счету, выполняемые банком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8907d09a675b9ee0ad63091e2bf02a0de192040a2066703b2b478bd351471cb"},{"code_id":"GK_RF_2","article_number":"849","version_date":"1994-11-30","article_text":"Банк обязан зачислять поступившие для клиента денежные средства не позднее дня, следующего за днем поступления в банк соответствующего платежного документа, если более короткий срок не предусмотрен законом, установленными в соответствии с ним банковскими правилами или договором банковского счета.\n\nБанк обязан по распоряжению клиента выдавать или списывать со счета денежные средства клиента не позднее дня, следующего за днем поступления в банк соответствующего платежного документа, если иные сроки не предусмотрены законом, изданными в соответствии с ним банковскими правилами или договором банковского счета.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 849. Сроки операций по счету","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10d5a0b91b27af206c6ddb92912ea769fef54b605e7d0a10148422ebaa465849"},{"code_id":"GK_RF_2","article_number":"850","version_date":"1994-11-30","article_text":"1. В случаях, когда в соответствии с договором банковского счета банк осуществляет платежи со счета несмотря на отсутствие денежных средств (кредитование счета), банк считается предоставившим клиенту кредит на соответствующую сумму с момента осуществления такого платежа.\n\n2. Права и обязанности сторон, связанные с кредитованием счета, определяются правилами о займе и кредите (глава 42), если договором банковского счета не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 850. Кредитование счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33bb465c404aee3e829eec4b649111e734ed55c6a0b63ab535ebb4b6856fb68f"},{"code_id":"GK_RF_2","article_number":"851","version_date":"1994-11-30","article_text":"1. В случаях, предусмотренных договором банковского счета, клиент оплачивает услуги банка по совершению операций с денежными средствами, находящимися на счете.\n\n2. Плата за услуги банка, предусмотренная пунктом 1 настоящей статьи, может взиматься банком по истечении каждого квартала из денежных средств клиента, находящихся на счете, если иное не предусмотрено договором банковского счета.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 851. Оплата расходов банка на совершение операций по счету","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4376a40579dde68b30bbf841457ac0c59da56155a766ea660069266eaa7a256f"},{"code_id":"GK_RF_2","article_number":"852","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором банковского счета, за пользование денежными средствами, находящимися на банковском счете клиента, банк уплачивает проценты в размере, определяемом договором банковского счета, сумма которых зачисляется на счет.\n\nСумма процентов зачисляется на счет в сроки, предусмотренные договором, а в случае, когда такие сроки договором не предусмотрены, по истечении каждого квартала.\n\n2. Если в договоре банковского счета не определен размер процентов, указанных в пункте 1 настоящей статьи, проценты уплачиваются в размере, обычно уплачиваемом банком по вкладам до востребования (статья 838).\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 852. Проценты за пользование банком денежными средствами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dc25d911410546de35c2d5da0c87ab80c1e8c236a02b3afc85dbf55ba2ebdc69"},{"code_id":"GK_RF_2","article_number":"853","version_date":"1994-11-30","article_text":"Денежные требования банка к клиенту, связанные с кредитованием счета (статья 850) и оплатой услуг банка (статья 851), а также требования клиента к банку об уплате процентов за пользование денежными средствами (статья 852) прекращаются зачетом (статья 410), если иное не предусмотрено договором банковского счета.\n\nЗачет указанных требований осуществляется банком. Банк обязан информировать клиента о произведенном зачете в порядке и в сроки, которые предусмотрены договором, а если соответствующие условия сторонами не согласованы, - в порядке и в сроки, которые являются обычными для банковской практики предоставления клиентам информации о состоянии денежных средств на соответствующем счете.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 853. Зачет встречных требований банка и клиента по счету","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b7acb7529f4ee4bd59b132b2107afc8eac5d3525805599b82baf00b9bd09bd9"},{"code_id":"GK_RF_2","article_number":"854","version_date":"1994-11-30","article_text":"1. Списание денежных средств со счета осуществляется банком на основании распоряжения клиента.\n\n2. Без распоряжения клиента списание денежных средств, находящихся на счете, допускается по решению суда, а также в случаях, установленных законом или предусмотренных договором между банком и клиентом.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 854. Основания списания денежных средств со счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8465d7215db1d8bffee32aeb50e0a94325169cb07bae3d85f43eb984493d7bc1"},{"code_id":"GK_RF_2","article_number":"855","version_date":"1994-11-30","article_text":"1. При наличии на счете денежных средств, сумма которых достаточна для удовлетворения всех требований, предъявленных к счету, списание этих средств со счета осуществляется в порядке поступления распоряжений клиента и других документов на списание (календарная очередность), если иное не предусмотрено законом.\n\n2. При недостаточности денежных средств на счете для удовлетворения всех предъявленных к нему требований списание денежных средств осуществляется в следующей очередности:\n\nв первую очередь по исполнительным документам, предусматривающим перечисление или выдачу денежных средств со счета для удовлетворения требований о возмещении вреда, причиненного жизни или здоровью, а также требований о взыскании алиментов;\n\nво вторую очередь по исполнительным документам, предусматривающим перечисление или выдачу денежных средств для расчетов по выплате выходных пособий и оплате труда с лицами, работающими или работавшими по трудовому договору (контракту), по выплате вознаграждений авторам результатов интеллектуальной деятельности;\n\nв третью очередь по платежным документам, предусматривающим перечисление или выдачу денежных средств для расчетов по оплате труда с лицами, работающими по трудовому договору (контракту), поручениям налоговых органов на списание и перечисление задолженности по уплате налогов и сборов в бюджеты бюджетной системы Российской Федерации, а также поручениям органов контроля за уплатой страховых взносов на списание и перечисление сумм страховых взносов в бюджеты государственных внебюджетных фондов;\n\nв четвертую очередь по исполнительным документам, предусматривающим удовлетворение других денежных требований;\n\nв пятую очередь по другим платежным документам в порядке календарной очередности.\n\nСписание средств со счета по требованиям, относящимся к одной очереди, производится в порядке календарной очередности поступления документов.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 855. Очередность списания денежных средств со счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ad6fec24d226afa713b39536ebf17d0bee28144ecee7aa357f6fbcf25b72e2f"},{"code_id":"GK_RF_2","article_number":"856","version_date":"1994-11-30","article_text":"В случаях несвоевременного зачисления банком на счет клиента поступивших клиенту денежных средств либо их необоснованного списания со счета, а также невыполнения или несвоевременного выполнения указаний клиента о перечислении денежных средств со счета либо об их выдаче со счета банк обязан уплатить на эту сумму проценты в порядке и в размере, которые предусмотрены статьей 395 настоящего Кодекса, независимо от уплаты процентов, предусмотренных пунктом 1 статьи 852 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 856. Ответственность банка за ненадлежащее совершение операций по банковскому счету","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d1e57531668a308bc9f285c78e5b65345e720babd4af52f312f2f784d31ebd3"},{"code_id":"GK_RF_2","article_number":"857","version_date":"1994-11-30","article_text":"1. Банк гарантирует тайну банковского счета и банковского вклада, операций по счету и сведений о клиенте.\n\n2. Сведения, составляющие банковскую тайну, могут быть предоставлены только самим клиентам или их представителям, а также представлены в бюро кредитных историй на основаниях и в порядке, которые предусмотрены законом. Государственным органам и их должностным лицам, а также иным лицам такие сведения могут быть предоставлены исключительно в случаях и порядке, которые предусмотрены законом.\n\n3. В случае разглашения банком сведений, составляющих банковскую тайну, клиент, права которого нарушены, вправе потребовать от банка возмещения причиненных убытков.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 857. Банковская тайна","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bc53324647f8705d7796ac04f09699c86f1ba9fbbcf36b51f692e7aa15bc61ba"},{"code_id":"GK_RF_2","article_number":"858","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором, ограничение распоряжения денежными средствами, находящимися на счете, не допускается, за исключением наложения ареста на денежные средства, находящиеся на счете, или приостановления операций по счету, в том числе блокирования (замораживания) денежных средств в случаях, предусмотренных законом.\n\n2. Не допускается арест денежных средств на совместном счете по обязательствам одного из владельцев такого счета в размере, превышающем установленную договором или законом долю денежных средств, принадлежащих этому владельцу совместного счета.\n\nВ случае, когда договор совместного банковского счета заключен клиентами-супругами, между которыми не заключен брачный договор, арест денежных средств на совместном счете осуществляется в соответствии с правилами семейного законодательства об обращении взыскания на имущество супругов по общим обязательствам супругов и по обязательствам одного из них.\n\n3. Расторжение договора банковского счета не является основанием для снятия ареста, наложенного на денежные средства, находящиеся на счете, или отмены приостановления операций по счету. В этом случае указанные меры по ограничению распоряжения счетом распространяются на остаток денежных средств на счете (пункт 5 статьи 859).\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 858. Ограничение распоряжения счетом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e37f891bb96298fb7b7c36fff17ba4a9410ff1390083fd826ee81721208fa304"},{"code_id":"GK_RF_2","article_number":"859","version_date":"1994-11-30","article_text":"1. Договор банковского счета расторгается по заявлению клиента в любое время.\n\n2. При отсутствии в течение двух лет денежных средств на счете клиента - гражданина, не являющегося индивидуальным предпринимателем, и операций по этому счету банк вправе в одностороннем порядке отказаться от исполнения договора банковского счета, предупредив клиента об этом в письменной форме или иным предусмотренным договором способом, если договором банковского счета не предусмотрен отказ банка от этого права. Договор банковского счета считается расторгнутым по истечении двух месяцев со дня направления банком такого предупреждения, если на счет клиента в течение этого срока не поступили денежные средства.\n\nПри отсутствии в течение двух лет или в течение иного предусмотренного договором банковского счета срока операций по этому счету клиента - юридического лица или индивидуального предпринимателя банк вправе в одностороннем порядке отказаться от исполнения договора банковского счета, предупредив клиента об этом в письменной форме или иным способом, предусмотренным договором, если договором банковского\n\nсчета не предусмотрен отказ банка от этого права. При этом указанный срок в любом случае не может быть менее шести месяцев. Договор банковского счета считается расторгнутым по истечении двух месяцев со дня направления банком такого предупреждения.\n\n3. Банк вправе расторгнуть договор банковского счета в случаях, установленных законом, с обязательным письменным уведомлением об этом клиента. Договор банковского счета считается расторгнутым по истечении шестидесяти дней со дня направления банком клиенту уведомления о расторжении договора банковского счета.\n\nСо дня направления банком клиенту уведомления о расторжении договора банковского счета до дня, когда договор считается расторгнутым, банк не вправе осуществлять операции по банковскому счету клиента, за исключением операций по взиманию платы за услуги банка, начислению процентов, если такие условия содержатся в договоре банковского счета, по перечислению обязательных платежей в бюджет и операций, предусмотренных пунктами 5 и 6 настоящей статьи.\n\n4. По требованию банка договор банковского счета может быть расторгнут судом в следующих случаях:\n\nкогда сумма денежных средств, находящихся на счете клиента, окажется ниже минимального размера, предусмотренного банковскими правилами или договором, если такая сумма не будет восстановлена в течение месяца со дня предупреждения банка об этом;\n\nпри отсутствии операций по этому счету в течение года, если иное не предусмотрено договором.\n\n5. Остаток денежных средств на счете выдается клиенту либо по его указанию перечисляется на другой счет не позднее семи дней после получения соответствующего письменного заявления клиента, за исключением случаев, предусмотренных пунктом 3 статьи 858 настоящего Кодекса.\n\n6. В случае неявки клиента за получением остатка денежных средств на счете в течение шестидесяти дней со дня направления банком клиенту уведомления о расторжении договора банковского счета либо неполучения банком в течение указанного срока указания клиента о переводе суммы остатка денежных средств на другой счет банк обязан зачислить денежные средства на специальный счет в Банке России, порядок открытия и ведения которого, а также порядок зачисления и возврата денежных средств с которого устанавливается Банком России. При этом в случае расторжения договора банковского счета в иностранной валюте банк обязан осуществить продажу иностранной валюты, а в случае расторжения договора банковского счета в драгоценных металлах осуществить продажу драгоценного металла по курсу, установленному этим банком на день продажи иностранной валюты и (или) драгоценного металла, и перечислить денежные средства в валюте Российской Федерации на указанный счет в Банке России.\n\nПо требованию клиента банк осуществляет в порядке, установленном банковскими правилами, возврат денежных средств в валюте Российской Федерации в сумме, ранее перечисленной этим банком на специальный счет в Банке России.\n\n7. Расторжение договора банковского счета является основанием закрытия счета клиента.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 859. Расторжение договора банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad6862b55b7c65ba07e9f51019353fa40ae7c4f905d47f899cc9b26ea5dfd773"},{"code_id":"GK_RF_2","article_number":"859.1","version_date":"1994-11-30","article_text":"1. По договору банковского счета в драгоценных металлах банк обязуется принимать и зачислять поступающий на счет, открытый клиенту (владельцу счета), драгоценный металл, а также выполнять распоряжения клиента о его перечислении на счет, о выдаче со счета драгоценного металла того же наименования и той же массы либо о выдаче на условиях и в порядке, которые предусмотрены договором, денежных средств в сумме, эквивалентной стоимости этого металла.\n\nПорядок осуществления операций по банковскому счету в драгоценных металлах регулируется законом, а также установленными в соответствии с ним банковскими правилами.\n\n2. Договор банковского счета в драгоценных металлах должен содержать обязательное указание на наименование драгоценного металла, а также порядок расчета суммы денежных средств, подлежащих выдаче со счета, если возможность их выдачи предусмотрена договором.\n\n3. Если иное не установлено законом, установленными в соответствии с ним банковскими правилами или не вытекает из существа счета, к отношениям по договору банковского счета в драгоценных металлах, а также к отношениям, возникающим при проведении операций по счету, применяются правила о счетах, предусмотренные настоящим Кодексом, в том числе правила абзаца седьмого пункта 1 статьи 64 настоящего Кодекса.\n\nК отношениям по договору банковского счета в драгоценных металлах правила пункта 1 статьи 840 настоящего Кодекса об обеспечении возврата вкладов граждан путем осуществляемого в соответствии с законом страхования вкладов физических лиц не применяются, о чем клиент-гражданин должен быть уведомлен в письменной форме до заключения договора банковского счета в драгоценных металлах, а банк должен получить от гражданина подтверждение того, что такое уведомление было совершено.\n\n4. Совместный счет, номинальный счет, публичный депозитный счет и иные виды банковских счетов, предусмотренных законом, могут быть счетами в драгоценных металлах.\n\n(Дополнение статьей - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 859.1. Особенности договора банковского счета в драгоценных металлах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d694a054b0841ed89279370ced2be681b2a4d9dd88cf4a58e1a6b7a5c91d270e"},{"code_id":"GK_RF_2","article_number":"860","version_date":"1994-11-30","article_text":"1. Общие положения о банковском счете применяются к отдельным видам банковских счетов (совместный счет, номинальный счет, публичный депозитный счет и иные виды банковских счетов, предусмотренных законом), если правилами об этих видах банковских счетов, предусмотренными главой 45 настоящего Кодекса и иными законами, не установлено иное.\n\n2. К договору залогового счета общие положения о банковском счете применяются в части, не урегулированной правилами о залоге прав по договору банковского счета (статьи 3589 - 35814).\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860. Применение общих положений о банковском счете к отдельным видам банковских счетов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"238ed97f0ac20065dc6a2a10a5ed9040713506c155afb45ba5ffa8f886543557"},{"code_id":"GK_RF_2","article_number":"860.1","version_date":"1994-11-30","article_text":"1. Номинальный счет может открываться владельцу счета для совершения операций с денежными средствами, права на которые принадлежат другому лицу-бенефициару.\n\nПрава на денежные средства, поступающие на номинальный счет, в том числе в результате их внесения владельцем счета, принадлежат бенефициару.\n\nНоминальный счет может открываться для совершения операций с денежными средствами, права на которые принадлежат нескольким лицам-бенефициарам, за исключением случаев, установленных законом.\n\nВ случаях, предусмотренных законом, владелец счета может быть одновременно одним из нескольких бенефициаров, при этом в отношениях с банком такое лицо обязано всякий раз указывать, что действует в качестве владельца счета или в качестве бенефициара. (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\n2. Существенным условием договора номинального счета является указание бенефициара либо порядка получения информации от владельца счета о бенефициаре или бенефициарах, а также основание их участия в отношениях по договору номинального счета.\n\n3. Законом или договором номинального счета с участием бенефициара на банк может быть возложена обязанность контролировать использование владельцем счета денежных средств в интересах бенефициара в пределах и в порядке, которые предусмотрены законом или договором.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.1. Договор номинального счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d9baee99953847067844e6911f0d63374fdc6e54671876dd7481bf61363f694"},{"code_id":"GK_RF_2","article_number":"860.10","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором эскроу, закрытие счета эскроу осуществляется банком по истечении срока действия или прекращения по иным основаниям договора эскроу. Правила, установленные пунктами 1 и 2 статьи 859 настоящего Кодекса, не применяются к отношениям по счету эскроу.\n\n2. Если иное не предусмотрено соглашением депонента и бенефициара, при расторжении договора счета эскроу остаток денежных средств перечисляется или выдается депоненту либо при возникновении оснований для передачи денежных средств бенефициару перечисляется или выдается бенефициару.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Дополнение параграфом - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.10. Закрытие счета эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fb9f38b6470bc9ddcc40a4dd2078b903fd7136fcea73196b310843f6af51ab1b"},{"code_id":"GK_RF_2","article_number":"860.11","version_date":"1994-11-30","article_text":"1. По договору публичного депозитного счета, заключаемому для целей депонирования денежных средств в случаях, предусмотренных законом, банк обязуется принимать и зачислять в пользу бенефициара денежные средства, поступающие от должника или иного указанного в законе лица (депонента), на счет, открытый владельцу счета (нотариусу, службе судебных приставов, суду и иным органам или лицам, которые в соответствии с законом могут принимать денежные средства в депозит).\n\nПубличный депозитный счет может открываться в российских кредитных организациях, величина собственных средств (капитала) которых составляет не менее чем двадцать миллиардов рублей. В течение месяца со дня, когда владельцу публичного депозитного счета стало известно или должно было стать известно о том, что величина капитала кредитной организации составила менее указанной суммы, он обязан закрыть свой публичный счет в этой кредитной организации и перечислить все средства с него на другой свой публичный депозитный счет в другой российской кредитной организации, величина капитала которой составляет не менее указанной суммы.\n\n2. По договору публичного депозитного счета банк не вправе контролировать соответствие операций владельца публичного депозитного счета установленным законом правилам о депонировании, если иное не предусмотрено законом.\n\n3. Депонирование денежных средств на публичном депозитном счете влечет за собой возникновение требования к владельцу счета в отношении этих денежных средств у лица, в чью пользу они депонированы (бенефициар). Бенефициар не вправе требовать совершения операций с денежными средствами, поступившими на публичный депозитный счет в его пользу, непосредственно от банка.\n\n4. Бенефициар вправе потребовать от владельца счета перечисления (выдачи) бенефициару денежных средств с публичного депозитного счета по основаниям и в порядке, которые предусмотрены законом.","article_title":"Статья 860.11. Договор публичного депозитного счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e27c2c98b30098d5d2f77be35e2fa16cfddcde4a607dd1d8afe37a6d8e9ba800"},{"code_id":"GK_RF_2","article_number":"860.12","version_date":"1994-11-30","article_text":"1. По публичному депозитному счету на основании поручения (распоряжения) владельца счета могут совершаться операции по перечислению или выдаче депонированных денежных средств бенефициару и возврату этих денежных средств депоненту либо по его указанию другому лицу.\n\nСовершение иных операций по публичному депозитному счету и кредитование счета (статья 850) не допускаются, если иное не предусмотрено законом.\n\n2. Владелец публичного депозитного счета несет ответственность перед бенефициаром и депонентом за совершение операций по такому счету с нарушением правил о депонировании, установленных законом.\n\n3. Банк не несет ответственности перед бенефициаром и депонентом за совершение операций по публичному депозитному счету на основании поручения (распоряжения) владельца счета с нарушением установленных законом правил о депонировании, за исключением случая, когда банк не исполнил установленную в соответствии с законом обязанность по контролю за использованием денежных средств на счете.","article_title":"Статья 860.12. Операции по публичному депозитному счету, совершаемые банком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8713f66bf1bdc3b79e35fa2f9dab4a557d58c7de537956cf1f4dbb32564efcc"},{"code_id":"GK_RF_2","article_number":"860.13","version_date":"1994-11-30","article_text":"1. За пользование денежными средствами, находящимися на публичном депозитном счете, банк уплачивает проценты, сумма которых зачисляется на счет.\n\n2. Проценты, указанные в пункте 1 настоящей статьи, уплачиваются банком в размере, который обычно уплачивается банком по вкладам до востребования (статья 838), если иной размер процентов не предусмотрен договором публичного депозитного счета.\n\n3. Выплата депонированных для бенефициара денежных средств, а также их возврат депоненту осуществляется с учетом уплаченных или подлежащих уплате банком процентов за период с момента поступления депонированных денежных средств на публичный депозитный счет до их выплаты бенефициару или возврата депоненту за вычетом вознагражде\n\nния, причитающегося банку по договору публичного депозитного счета.","article_title":"Статья 860.13. Проценты за пользование банком денежными средствами, находящимися на публичном депозитном счете","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06d91699923bf0ee0d2de1c81351e45f08949f1bae6a6ac699f2001b7851bda8"},{"code_id":"GK_RF_2","article_number":"860.14","version_date":"1994-11-30","article_text":"1. Арест, приостановление операций и списание денежных средств, находящихся на публичном депозитном счете, по обязательствам владельца счета перед его кредиторами и по обязательствам бенефициара или депонента не допускаются. Взыскание по обязательствам бенефициара или депонента может быть обращено на их право требования к владельцу счета.\n\n2. В случае неисполнения владельцем счета предусмотренной законом обязанности по выдаче или возврату депонированных денежных средств бенефициар или депонент вправе потребовать от владельца счета совершения соответствующих действий в судебном порядке.","article_title":"Статья 860.14. Распоряжение денежными средствами, находящимися на публичном депозитном счете","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1becb3e4bebffc529d503b83eedc144f7cbbb5b015989a533e0c0e9f4002aebb"},{"code_id":"GK_RF_2","article_number":"860.15","version_date":"1994-11-30","article_text":"1. В случае смерти нотариуса (иного уполномоченного на открытие публичного депозитного счета лица) или сложения им (прекращения) своих полномочий владелец публичного депозитного счета заменяется на другого нотариуса (иное лицо), которому в соответствии с законом, иными правовыми актами передаются дела нотариуса (иного лица), являвшегося владельцем счета.\n\n2. В случае упразднения или преобразования органа, который уполномочен на открытие публичного депозитного счета, владелец такого счета заменяется на другой орган, к компетенции которого в соответствии с законом, иными правовыми актами относится открытие публичного депозитного счета для депонирования денежных средств соответствующих депонентов.\n\n3. Договор публичного депозитного счета не может быть прекращен по основаниям, указанным в пунктах 2 и 4 статьи 859 настоящего Кодекса.","article_title":"Статья 860.15. Замена владельца публичного депозитного счета и прекращение договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2620b025ca1c59084b8dd7137d4623ecb28c1022babc54842f18e5716794dead"},{"code_id":"GK_RF_2","article_number":"860.2","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.2. Заключение договора номинального счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1bb7373971a1cd726858adc9707e8a30028e7b9a060f1c799b0109da42a90dc"},{"code_id":"GK_RF_2","article_number":"860.3","version_date":"1994-11-30","article_text":"Законом или договором номинального счета может быть ограничен круг операций, которые могут совершаться по указанию владельца счета, в том числе путем определения:\n\n1) лиц, которым могут перечисляться или выдаваться денежные средства;\n\n2) лиц, с согласия которых совершаются операции по счету;\n\n3) документов, являющихся основанием совершения операций;\n\n4) иных обстоятельств.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.3. Операции по номинальному счету","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"09dbe1149c1b61bf011c77d1f0854727bf0e6f2ac56e6a2066a1ccd99b2b10bd"},{"code_id":"GK_RF_2","article_number":"860.4","version_date":"1994-11-30","article_text":"1. Бенефициар по договору номинального счета вправе требовать от банка предоставления сведений, составляющих банковскую тайну, если такое право предоставлено бенефициару договором.\n\n2. Бенефициар по договору номинального счета с участием бенефициара вправе требовать от банка предоставления сведений, составляющих банковскую тайну.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.4. Предоставление сведений, составляющих банковскую тайну, бенефициару по договору номинального счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e1f9c9d1264206793774aef0eff8fb6d2cae30c410c822b99c0cc954c858407"},{"code_id":"GK_RF_2","article_number":"860.5","version_date":"1994-11-30","article_text":"1. Приостановление операций по номинальному счету, арест или списание денежных средств, находящихся на номинальном счете, по обязательствам владельца счета, за исключением обязательств, предусмотренных статьями 850 и 851 настоящего Кодекса, не допускается.\n\n2. Арест или списание денежных средств с номинального счета по обязательствам бенефициара допускается по решению суда. Списание денежных средств с номинального счета допускается также в случаях, предусмотренных законом или договором номинального счета.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.5. Арест или списание денежных средств, находящихся на номинальном счете","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bba4f9abafcbea268adf7c0c537661cfeb3a9104f0c29ffc95f1e21f27532c9"},{"code_id":"GK_RF_2","article_number":"860.6","version_date":"1994-11-30","article_text":"1. Договор номинального счета с участием бенефициара может быть изменен или расторгнут только с согласия бенефициара, если законом или договором номинального счета не предусмотрено иное.\n\n2. В случае поступления в банк заявления владельца счета о расторжении договора номинального счета банк обязан незамедлительно проинформировать об этом бенефициара.\n\n3. Если владельцем номинального счета является опекун или попечитель бенефициара, при прекращении исполнения обязанностей опекуна или попечителя такой владелец номинального счета заменяется на другого владельца, который в установленном законом порядке назначен опекуном или попечителем бенефициара. При прекращении опеки или попечительства в случаях, предусмотренных законом, в том числе при достижении бенефициаром совершеннолетия, договор номинального счета прекращается, остаток денежных средств по заявлению бенефициара выдается ему или перечисляется на другой его банковский счет.\n\n4. При расторжении договора номинального счета остаток денежных средств перечисляется на другой номинальный счет владельца или выдается бенефициару либо, если иное не предусмотрено законом или договором номинального счета либо не вытекает из существа отношений, по указанию бенефициара перечисляется на другой счет.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.6. Изменение и расторжение договора номинального счета, замена владельца номинального счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e7a87b17ef8a1377c93c03bb7cf44bd59c747575f179904f97ab3d2f6fd0e88"},{"code_id":"GK_RF_2","article_number":"860.7","version_date":"1994-11-30","article_text":"1. По договору счета эскроу банк (эскроу-агент) открывает специальный счет эскроу для учета и блокирования денежных средств, полученных им от владельца счета (депонента) в целях их передачи другому лицу (бенефициару) при возникновении оснований, предусмотренных договором счета эскроу. Права на денежные средства, находящиеся на счете эскроу, принадлежат депоненту до даты возникновения оснований для передачи денежных средств бенефициару, а после указанной даты - бенефициару. Распоряжение денежными средствами, находящимися на счете эскроу, осуществляется в порядке, предусмотренном настоящим параграфом.\n\n2. Обязательства по договору счета эскроу могут содержаться наряду с договором счета эскроу в ином договоре, по которому эскроу-агентом является банк.\n\n3. Вознаграждение банка как эскроу-агента не может взиматься из денежных средств, находящихся на счете эскроу, если иное не предусмотрено договором.\n\n4. К отношениям сторон применяются общие положения о банковском счете и договоре эскроу (глава 471), если иное не предусмотрено настоящей статьей и статьями 8608 - 86010 настоящего Кодекса или не вытекает из существа отношений сторон.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.7. Договор счета эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"240677eb6196a8d6e111a2547577e2bd1c28301f580d8d56a86674ca5d999808"},{"code_id":"GK_RF_2","article_number":"860.8","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором, ни депонент, ни бенефициар не вправе распоряжаться денежными средствами, находящимися на счете эскроу, за исключением случаев, указанных в настоящей статье.\n\n2. Зачисление на счет эскроу иных денежных средств депонента, за исключением депонируемой суммы, указанной в договоре эскроу, не допускается.\n\n3. При возникновении оснований, предусмотренных договором счета эскроу, банк в установленный таким договором срок, а при его отсутствии - в течение десяти дней обязан выдать бенефициару депонированную сумму или перечислить ее на указанный им счет.\n\n4. Приостановление операций по счету эскроу, арест или списание денежных средств, находящихся на счете эскроу, по обязательствам депонента перед третьими лицами и по обязательствам бенефициара не допускается.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.8. Ограничения по распоряжению денежными средствами и использованию счета эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d121a514c0215a0c38d4820f014f7aae0b217031b5b1a1724e79e5d8ceec3eab"},{"code_id":"GK_RF_2","article_number":"860.9","version_date":"1994-11-30","article_text":"Право требовать от банка предоставления сведений, составляющих банковскую тайну, имеют как депонент, так и бенефициар.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.9. Предоставление сведений, составляющих банковскую тайну, по договору счета эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6fda4f5f5a92837ba3d1e6167816d9df4ca67b18320560aa22698cb66d1e89e9"},{"code_id":"GK_RF_2","article_number":"861","version_date":"1994-11-30","article_text":"1. Расчеты с участием граждан, не связанные с осуществлением ими предпринимательской деятельности, могут производиться наличными деньгами (статья 140) без ограничения суммы или в безналичном порядке.","article_title":"Статья 861. Наличные и безналичные расчеты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aedb79c87a38d92ec134e3d084d188bcb96af825e4bcf41ac91b28518a8359b3"},{"code_id":"GK_RF_2","article_number":"862","version_date":"1994-11-30","article_text":"Расчеты цифровыми рублями могут осуществляться в формах, установленных законодательством Российской Федерации о национальной платежной системе. (Дополнение абзацем - Федеральный закон от 24.07.2023 № 339-ФЗ)\n\n(Пункт в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 862. Формы безналичных расчетов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7fdcc1e5e918905577de702b8a8f1a0eaad0f99ddf71856e0693a7c61b695b99"},{"code_id":"GK_RF_2","article_number":"863","version_date":"1994-11-30","article_text":"1. При расчетах платежными поручениями банк плательщика обязуется по распоряжению плательщика перевести находящиеся на его банковском счете денежные средства на банковский счет получателя средств в этом или ином банке в сроки, предусмотренные законом, если более короткий срок не предусмотрен договором банковского счета либо не определен применяемыми в банковской практике обычаями.\n\n2. Порядок осуществления расчетов платежными поручениями регулируется законом, банковскими правилами, применяемыми в банковской практике обычаями или договором.\n\n3. Банк плательщика вправе привлекать другие банки (банки-посредники) для исполнения платежного поручения плательщика.\n\n4. Правила настоящего параграфа применяются к отношениям, связанным с осуществлением расчетов поручениями о переводе денежных средств без открытия банковского счета, с учетом особенностей, предусмотренных статьей 8661 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 863. Общие положения о расчетах платежными поручениями","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01a95310c4a96b90c88281a9864a0db6cbb43a1173e0efd298e4d132db239365"},{"code_id":"GK_RF_2","article_number":"864","version_date":"1994-11-30","article_text":"1. Содержание (реквизиты) платежного поручения и его форма должны соответствовать требованиям, предусмотренным законом и банковскими правилами.\n\n2. При приеме к исполнению платежного поручения банк обязан удостовериться в праве плательщика распоряжаться денежными средствами, проверить соответствие платежного поручения установленным требованиям, достаточность денежных средств для исполнения платежного поручения, а также выполнить иные процедуры приема к исполнению распоряжений, предусмотренные законом, банковскими правилами и договором.\n\nПри отсутствии оснований для исполнения платежного поручения банк отказывает в приеме такого платежного поручения к исполнению с уведомлением об этом плательщика в срок не позднее дня, следующего за днем получения платежного поручения, если более короткий срок не установлен банковскими правилами и договором.\n\n3. Достаточность денежных средств, находящихся на банковском счете плательщика, для исполнения платежного поручения определяется в порядке, установленном законом, банковскими правилами и договором с учетом требований статьи 855 настоящего Кодекса.\n\nЕсли иное не предусмотрено законом, банковскими правилами и договором, при недостаточности денежных средств, находящихся на банковском счете плательщика, для исполнения платежного поручения банк не принимает платежное поручение к исполнению и уведомляет об этом плательщика в срок не позднее дня, следующего за днем поступления в банк платежного поручения.\n\n4. Прием платежного поручения к исполнению подтверждается банком в порядке, предусмотренном законом, банковскими правилами и договором.\n\n5. Платежное поручение может быть отозвано плательщиком до наступления момента безотзывности перевода денежных средств, определяемого в соответствии с законом.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 864. Прием к исполнению банком платежного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"979f66ff3162b1cfa9010a897525eb6b65fcf1001d30840d75a15aa1b9a6e830"},{"code_id":"GK_RF_2","article_number":"865","version_date":"1994-11-30","article_text":"1. Банк плательщика, принявший к исполнению платежное поручение, в соответствии с распоряжением плательщика обязан его исполнить одним из следующих способов:\n\n1) зачисление денежных средств на банковский счет получателя средств, открытый в этом же банке;\n\n2) зачисление денежных средств на банковский счет банка получателя средств, открытый в банке плательщика, либо передача платежного поручения банку получателя средств для списания денежных средств с банковского счета банка плательщика, открытого в банке получателя средств;\n\n3) передача платежного поручения банку-посреднику в целях зачисления денежных средств на банковский счет банка получателя средств;\n\n4) иные способы, предусмотренные банковскими правилами и договором.\n\n2. Банк обязан информировать плательщика об исполнении его платежного поручения в срок не позднее дня, следующего за днем исполнения платежного поручения, если более короткий срок не установлен банковскими правилами и договором. Порядок такого информирования определяется банковскими правилами и договором.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 865. Исполнение банком платежного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5bc8062628d8e203226d02c955dcf88a63094fe2ba57351d3b6db2e36ae37803"},{"code_id":"GK_RF_2","article_number":"866","version_date":"1994-11-30","article_text":"1. В случае неисполнения или ненадлежащего исполнения платежного поручения банк несет ответственность перед плательщиком в соответствии с главой 25 настоящего Кодекса с учетом положений, предусмотренных настоящей статьей.\n\n2. В случаях, если неисполнение или ненадлежащее исполнение платежного поручения имело место в связи с нарушением банком-посредником или банком получателя средств правил перевода денежных средств или договора между банками, ответственность перед плательщиком может быть возложена судом на банк-посредник или банк получателя средств, которые в этом случае отвечают перед плательщиком солидарно. Банк плательщика может быть привлечен к солидарной ответственности в указанных случаях, если он осуществил выбор банка-посредника.\n\n3. Если нарушение правил перевода денежных средств или условий договора повлекло несвоевременный перевод денежных средств, банки обязаны уплатить проценты в порядке и в размере, которые предусмотрены статьей 395 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 866. Ответственность банка за неисполнение или ненадлежащее исполнение платежного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aca9fdad2a392bec9c45891d6e0643b3d3da5b099d581dcadd9a80abdec76d6a"},{"code_id":"GK_RF_2","article_number":"866.1","version_date":"1994-11-30","article_text":"1. При переводе денежных средств без открытия банковского счета банк плательщика обязуется перевести без открытия банковского счета плательщику-гражданину на основании его распоряжения предоставленные им наличные денежные средства получателю средств в этом или ином банке.\n\n2. Достаточность денежных средств для исполнения распоряжения о переводе без открытия банковского счета определяется исходя из суммы предоставленных банку плательщиком наличных денежных средств.\n\n(Дополнение статьей - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 866.1. Особенности расчетов без открытия банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87289d876ffed07dadc19128197f562240bea4954854698f7b034b9797493c86"},{"code_id":"GK_RF_2","article_number":"867","version_date":"1994-11-30","article_text":"1. При расчетах по аккредитиву банк-эмитент, действующий по поручению плательщика, обязуется перед получателем средств произвести платежи или акцептовать и оплатить переводной вексель, выставленный получателем средств, либо совершить иные действия по исполнению аккредитива по представлении получателем средств предусмотренных аккредитивом документов и в соответствии с условиями аккредитива.\n\n2. Банк-эмитент может уполномочить другой банк (исполняющий банк) произвести платежи или акцептовать и оплатить переводной вексель, выставленный получателем средств, либо совершить иные действия по исполнению аккредитива по представлении получателем средств предусмотренных аккредитивом документов и в соответствии с условиями аккредитива.\n\nИсполняющий банк вправе принять поручение банка-эмитента или отказаться от такого поручения, направив банку-эмитенту соответствующее уведомление. Частичный отказ исполняющего банка от исполнения поручения не допускается. Исполняющий банк считается принявшим поручение банка-эмитента, если он прямо выразил на это согласие, в том числе путем совершения действий в соответствии с условиями аккредитива. Согласие исполняющего банка на исполнение аккредитива не препятствует его исполнению банком-эмитентом.\n\n3. В случае открытия покрытого (депонированного) аккредитива банк-эмитент обязан перечислить сумму аккредитива (покрытие) за счет плательщика либо предоставленного ему кредита в распоряжение исполняющего банка на весь срок действия обязательства банка-эмитента.\n\nВ случае открытия непокрытого (гарантированного) аккредитива банк-эмитент может предоставить исполняющему банку, принявшему поручение банка-эмитента, при осуществлении действий по исполнению аккредитива право списывать средства со счета банка-эмитента, открытого в исполняющем банке, в пределах суммы аккредитива либо может указать в аккредитиве иной способ возмещения исполняющему банку сумм, выплаченных им по аккредитиву. При исполнении непокрытого аккредитива исполняющий банк вправе не осуществлять исполнение аккредитива до поступления денежных средств от банка-эмитента, за исключением случая подтверждения аккредитива исполняющим банком.\n\n4. Аккредитив считается открытым с указанной в нем даты открытия аккредитива, если иное не предусмотрено законом, банковскими правилами и договором.\n\nБанк, дающий инструкции другому банку по совершению действий по аккредитиву, обязан оплачивать или компенсировать любые комиссии или затраты такого банка, связанные с выполнением им полученных инструкций. Банк-эмитент, пользующийся услугами другого банка для выполнения инструкций плательщика, делает это за счет плательщика и на его риск. Плательщик обязан возместить банку-эмитенту все расходы, понесенные им в связи с выполнением его инструкций по аккредитиву.\n\n5. Расчеты по аккредитиву регулируются настоящим Кодексом, банковскими правилами, условиями аккредитива, а в части, ими не урегулированной, обычаями, применяемыми в банковской практике.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 867. Общие положения о расчетах по аккредитиву","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"56c07d870cd14e042ff814fb5ba730f14a91ae9dad1505a224ef477a60ac98fe"},{"code_id":"GK_RF_2","article_number":"868","version_date":"1994-11-30","article_text":"1. Отзывный аккредитив может быть изменен или отменен по поручению плательщика банком-эмитентом в любой момент без предварительного уведомления получателя средств.\n\n2. Исполняющий банк осуществляет платеж или иные операции по отзывному аккредитиву, если к моменту их совершения им не получено уведомление банка-эмитента об изменении или отмене аккредитива.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 868. Отзывный аккредитив","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5bc7a564feff624c0fe04006a181795fd3f99b427c3da2f492755c3931d13673"},{"code_id":"GK_RF_2","article_number":"869","version_date":"1994-11-30","article_text":"1. Безотзывный аккредитив не может быть отменен банком-эмитентом без согласия получателя средств и банка, подтвердившего аккредитив. Безотзывный аккредитив не может быть изменен банком-эмитентом без согласия получателя средств.\n\n2. Для изменения или отмены безотзывного аккредитива по поручению плательщика банк-эмитент должен направить получателю средств соответствующее уведомление. Аккредитив считается отмененным или измененным с момента получения банком-эмитентом согласия получателя средств.\n\n3. Если аккредитив был подтвержден другим банком (статья 870), такой банк вправе не согласиться с изменением безотзывного аккредитива, при этом он обязан незамедлительно сообщить об этом банку-эмитенту и получателю средств.\n\n4. Аккредитив является безотзывным, если в его тексте не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 869. Безотзывный аккредитив","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a7d62972b830443ed4b9668c0420c6f2f1b4117ff1ec1b57082fad17ab76269"},{"code_id":"GK_RF_2","article_number":"870","version_date":"1994-11-30","article_text":"1. По просьбе банка-эмитента безотзывный аккредитив может быть подтвержден другим банком (подтверждающий банк). После подтверждения аккредитива подтверждающий банк становится обязанным перед бенефициаром по аккредитиву в пределах подтвержденной им суммы солидарно с банком-эмитентом.\n\nОбязательство подтверждающего банка возникает с момента направления получателю средств либо банку получателя уведомления о подтверждении аккредитива, если уведомлением не предусмотрено иное.\n\n2. В случае изменения аккредитива подтверждающий банк становится обязанным на измененных условиях аккредитива, если он дал на это согласие. В остальных случаях подтверждающий банк считается обязанным на прежних условиях аккредитива.\n\nОбязательство подтверждающего банка по аккредитиву с учетом внесенных в него изменений возникает с момента направления получателю либо банку получателя уведомления об этом, если уведомлением не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 870. Подтвержденный аккредитив","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f3aedccf9a09ff907b2886c6a4324b568f5a6f3c21ada49357bf50a34ad8724"},{"code_id":"GK_RF_2","article_number":"870.1","version_date":"1994-11-30","article_text":"1. Исполнение аккредитива может осуществляться лицу, указанному получателем средств, если возможность такого исполнения предусмотрена условиями аккредитива и исполняющий банк выразил свое согласие на такое исполнение (далее - переводной (трансферабельный) аккредитив). При этом получатель средств вправе определить документы, которые должны быть представлены указанным им лицом для исполнения переводного (трансферабельного) аккредитива. Эти документы могут быть не предусмотрены условиями переводного (трансферабельного) аккредитива.\n\nК отношениям, возникающим при исполнении аккредитива в соответствии с настоящей статьей, положения параграфа 1 главы 24 настоящего Кодекса не применяются.\n\n2. Получатель средств вправе указать лицо, которому должно производиться исполнение переводного (трансферабельного) аккредитива (далее - второй получатель средств) до момента представления им документов, соответствующих условиям открытого в его пользу аккредитива, в заявлении, представляемом в исполняющий банк. Получатель средств вправе указать несколько вторых получателей средств.\n\n3. Второй получатель средств не вправе указывать иное лицо, которому должен быть исполнен переводной (трансферабельный) аккредитив, за исключением получателя средств.\n\n4. Порядок и условия исполнения переводного (трансферабельного) аккредитива определяются законом, банковскими правилами и условиями аккредитива.\n\n(Дополнение статьей - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 870.1. Переводной (трансферабельный) аккредитив","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b847c2d51e6d19f4773e26d0d8f13d0b6c7f1db8a2fa64016ab28387eb45287f"},{"code_id":"GK_RF_2","article_number":"871","version_date":"1994-11-30","article_text":"1. Исполнение аккредитива может быть произведено путем:\n\n1) платежа получателю средств, осуществляемого банком по предъявлении ему документов, соответствующих условиям аккредитива, непосредственно либо в срок или сроки, предусмотренные условиями аккредитива;\n\n2) акцепта переводного векселя с его оплатой по наступлении срока платежа;\n\n3) иными способами, указанными в аккредитиве.\n\n2. Для исполнения аккредитива получатель средств представляет документы, в том числе в электронной форме, предусмотренные условиями аккредитива, в исполняющий банк или банк-эмитент. Исполняющий банк или банк-эмитент, получившие указанные документы, проверяют их в срок, не превышающий пяти рабочих дней со дня их получения, и принимают решение о выплате или об отказе от выплаты.\n\n3. Исполнение аккредитива производится при условии, что представленные документы по внешним признакам соответствуют условиям аккредитива, и не может быть обусловлено обязательством или обязательствами плательщика либо получателя средств, даже если в аккредитиве содержится ссылка на такое обязательство или такие обязательства.\n\n4. Проверка представленных документов осуществляется банком по внешним признакам.\n\nЕсли представленные документы по внешним признакам не соответствуют условиям аккредитива, банк вправе не исполнять аккредитив. Документы, которые по внешним признакам не соответствуют друг другу, должны рассматриваться как не соответствующие условиям аккредитива.\n\n5. В случае открытия покрытого (депонированного) аккредитива исполняющий банк исполняет аккредитив за счет покрытия по такому аккредитиву.\n\nЕсли исполняющий банк исполнил непокрытый (гарантированный) аккредитив, банк-эмитент или подтверждающий банк обязан возместить ему понесенные расходы. Указанные расходы возмещаются подтверждающему банку банком-эмитентом, а банку-эмитенту плательщиком. Плательщик обязан выплатить банку-эмитенту суммы, уплаченные по аккредитиву, независимо от исполнения банком-эмитентом своих обязательств перед исполняющим банком и подтверждающим банком, в том числе в случае, если исполняющим банком или подтверждающим банком банку-эмитенту предоставлена отсрочка.\n\n6. Документы, принятые исполняющим банком, представляются им в банк-эмитент или подтверждающий банк (при его наличии). Документы, принятые подтверждающим банком, представляются им в банк-эмитент. Банк, получивший представленные документы, проверяет их в срок, не превышающий пяти рабочих дней со дня их получения, и возмещает расходы по исполнению непокрыто\n\nго (гарантированного) аккредитива или отказывает в возмещении таких расходов. В случае установления банком, получившим представленные документы, несоответствия представленных документов условиям покрытого (депонированного) аккредитива банк, получивший представленные документы, вправе потребовать от исполняющего банка сумму денежных средств, перечисленных по исполненному аккредитиву.\n\n7. Получатель средств не вправе уступить полностью или частично право (требование) по аккредитиву, если иное не предусмотрено условиями аккредитива.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 871. Исполнение аккредитива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"892f0b1109fa2bf75e299b6a4c1174b60b1a84a4f2908bce01712a3db8a2fd7b"},{"code_id":"GK_RF_2","article_number":"872","version_date":"1994-11-30","article_text":"1. Банк-эмитент и подтверждающий банк, принявшие на себя обязательства по аккредитиву, несут перед получателем средств солидарную ответственность за неисполнение или ненадлежащее исполнение аккредитива при условии представления документов, соответствующих условиям аккредитива, и выполнения иных условий аккредитива.\n\nПри необоснованном отказе исполняющего банка в выплате денежных средств по аккредитиву ответственность перед получателем средств может быть возложена судом на исполняющий банк.\n\n2. Исполняющий банк, который принял поручение по исполнению аккредитива, несет ответственность за неисполнение или ненадлежащее исполнение аккредитива перед банком-эмитентом.\n\n3. Банк-эмитент, принявший к исполнению поручение плательщика об открытии и исполнении аккредитива, несет перед ним ответственность за неисполнение или ненадлежащее исполнение этого поручения. Подтверждающий банк, принявший к исполнению поручение банка-эмитента о подтверждении и исполнении аккредитива, несет ответственность за неисполнение или ненадлежащее исполнение этого поручения перед банком-эмитентом.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 872. Ответственность банков","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e9db48de42e5bdb44a88b36e814a5d3c06b55e477e5b8e21b497f593d88a8dc"},{"code_id":"GK_RF_2","article_number":"873","version_date":"1994-11-30","article_text":"1. Закрытие аккредитива в исполняющем банке производится:\n\n1) по истечении срока действия аккредитива, за исключением случая, когда документы по аккредитиву были представлены в пределах срока действия аккредитива;\n\n2) при полном исполнении аккредитива;\n\n3) по заявлению получателя средств об отказе от использования аккредитива до истечения срока его действия;\n\n4) по заявлению плательщика об отмене или отзыве аккредитива.\n\n2. О закрытии аккредитива исполняющий банк должен поставить в известность банк-эмитент.\n\n3. Неиспользованная сумма аккредитива подлежит возврату банку-эмитенту одновременно с закрытием аккредитива. Банк-эмитент обязан зачислить возвращенную денежную сумму на банковский счет плательщика, с которого депонировались эти средства.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 873. Закрытие аккредитива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e3c7cd67f1375c84a5dbb3434a5faf1da054b089fc2187cc1193594b3918ed6e"}]$law7v016$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
